INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-z7ytj', 'z7ytj', 'Psicologia da saúde: teoria, intervenção e pesquisa', NULL, '["Railda Sabino Fernandes Alves"]', 'EDUEPB', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Health Professions', 'Esta publicação é eminentemente didática e útil aos vários profissionais da área da saúde. A obra está organizada em duas partes. A primeira, dedicada à teoria da Psicologia da Saúde, visa dar ao leitor um panorama geral dos aspectos que embasam a compreensão da Segunda parte do livro voltada aos trabalhos de pesquisa desenvolvidos pelos pesquisadores da Psicologia da Saúde, aqui reunidos.', '["health psychology","health psychology theory","health psychology interventions","health psychology research","healthcare workers"]', '10.7476/9788578791926', '9788578791926', 'https://books.scielo.org/id/z7ytj', 'https://books.scielo.org/id/z7ytj/pdf/alves-9788578791926.pdf', NULL, 'https://books.scielo.org/id/z7ytj/cover/cover_thumbnail.jpeg', NULL, 6, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-z8477', 'z8477', 'A aventura de contar-se: feminismos, escrita de si e invenções da subjetividade', NULL, '["Luzia Margareth Rago"]', 'Editora da Unicamp', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Como as mulheres têm transformado o mundo e se transformado a si mesmas? Estas questões norteiam o presente trabalho, que busca entender como os feminismos, nas últimas quatro décadas, possibilitaram profundas e positivas mudanças na cultura e na sociedade brasileiras. Partindo das narrativas autobiográficas de sete militantes feministas, nascidas entre os anos 1940 e 1950, a autora investiga a maneira como essas mulheres abriram novos espaços na esfera pública e na vida política do Brasil, desde os violentos anos da ditadura militar. Mais do que isso, visa dar visibilidade aos processos de invenção da subjetividade pelos quais puderam afirmar novos modos de existência, mais integrados e libertários. Nessa direção, opera com os conceitos de “estéticas da existência” ou “artes do viver”, “parresia” e “escrita de si” da filosofia de Foucault, assim como com operadores de Deleuze e da teoria feminista pós-estruturalista.', '["feminism","women''s autobiography","self-writing","subjectivity","Brazilian feminism","autobiographical narrative","public sphere","women''s political participation","military dictatorship","feminist poststructuralism","Michel Foucault","Gilles Deleuze"]', '10.7476/9788526814691', '9788526810174', 'https://books.scielo.org/id/z8477', NULL, NULL, 'https://books.scielo.org/id/z8477/cover/cover_thumbnail.jpeg', 341, 66, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-z8c8x', 'z8c8x', 'Perspectivas turísticas: una discusión entre los social y lo cultural', NULL, '["Alvelayis Nieto Mejía"]', 'Editorial Fundación Universitaria San Mateo', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Business, Management and Accounting', 'Este libro titulado Perspectivas turísticas: una discusión entre lo social y lo cultural es un análisis de buenas prácticas en las cuales un grupo de investigadores centraron su indagación para evidenciar la importancia de construir un ejercicio social enfoca-do a identificar las problemáticas que se establecen dentro de los territorios mediante diferentes contextos que ilustran al lector para el desarrollo de alternativas inclinadas a superar los marcados desequilibrios sociales que deben afrontar los profesionales del turismo en la actualidad.', '["tourism","tourism workforce","tourism development","social imbalance","best practices"]', '10.7476/9786289558265', '9786289558265', 'https://books.scielo.org/id/z8c8x', 'https://books.scielo.org/id/z8c8x/pdf/nieto-9786289558265.pdf', NULL, 'https://books.scielo.org/id/z8c8x/cover/cover_thumbnail.jpeg', NULL, 5, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-z8mbp', 'z8mbp', 'Entre o Estado e a filantropia: assistência à lepra na cidade de Salvador, Bahia (1921-1936', NULL, '["Muller Sampaio"]', 'EDUNEB', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O objetivo do livro é compreender a atuação do poder público e da filantropia na assistência aos leprosos internados no Hospital/Leprosário D. Rodrigo José de Menezes, em Salvador Bahia. O recorte de tempo começa em 1921, quando a Bahia aderiu ao acordo com a União para realizar políticas sanitárias nacionais propostas pelo Departamento Nacional de Saúde Pública e termina em 1936, quando foram suspensas as obras no antigo edifício, localizado na Quinta dos Lázaros.', '["leprosy","leprosaria","Salvador, Bahia","philanthropy","public health policy","state intervention in health care","history of public health"]', '10.7476/9788585813345', '9786588211762', 'https://books.scielo.org/id/z8mbp', 'https://books.scielo.org/id/z8mbp/pdf/sampaio-9788585813345.pdf', 'https://books.scielo.org/id/z8mbp/epub/sampaio-9788585813345.epub', 'https://books.scielo.org/id/z8mbp/cover/cover_thumbnail.jpeg', 192, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-z8svf', 'z8svf', 'Paulo Freire, a cultura e a educação: pensando à sombra de uma mangueira', NULL, '["Débora Mazza"]', 'Editora da Unicamp', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Paulo Freire, a cultura e a educação foi redigido durante a pandemia da Covid-19. O livro traz uma tessitura teórica composta por sete textos organizados segundo uma linha histórico-cronológica da vida, do trabalho e das obras de Paulo Freire. Ousa brincar com a metáfora da mangueira que comparece em inúmeras circunstâncias na vida e nos textos de Paulo. Essa árvore lança luz e sombra, acolhida e fuga em sua “andarilhagem” pelo campo da cultura e da educação do povo nas Américas, na Europa e na África.', '["Paulo Freire","education and culture","critical pedagogy","COVID-19 pandemic","popular education","Latin America","Europe","Africa"]', '10.7476/9788526816657', '9788526815735', 'https://books.scielo.org/id/z8svf', NULL, NULL, 'https://books.scielo.org/id/z8svf/cover/cover_thumbnail.jpeg', 229, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-z9374', 'z9374', 'A saúde no Brasil em 2030: estrutura do financiamento e do gasto setorial - Vol. 4', NULL, '["Fundação Oswaldo Cruz"]', 'Fiocruz/Ipea/Ministério da Saúde/Secretaria de Assuntos Estratégicos da Presidência da República', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Este volume, Estrutura do Financiamento e do Gasto Setorial, apresenta artigos que abordam os problemas e perspectivas do financiamento da Saúde no Brasil, bem como as estruturas do financiamento e do gasto setorial, o papel do financiamento público e privado na prestação dos serviços de saúde, suas repercussões sobre a oferta de serviços e os modos de pagamento e compra de serviços.', '["health care financing","health care costs","public health funding","health care delivery","health care payment models","health care purchasing","Brazil"]', '10.7476/9788581100180', '9788581100180', 'https://books.scielo.org/id/z9374', 'https://books.scielo.org/id/z9374/pdf/noronha-9788581100180.pdf', NULL, 'https://books.scielo.org/id/z9374/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-z9kn7', 'z9kn7', 'Arquivo de um sequestro jurídico-psiquiátrico: o caso Juvenal', 'o caso Juvenal', '["Luciana Brito"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', '“Na manhã de 29.05.1968 no Sítio Morada Nova, o acusado desfechou, utilizando uma roçadeira, violentos ferimentos na pessoa de seu próprio irmão”, narrava a denúncia do Ministério Público. O acusado era Juvenal Raimundo de Araújo, talvez Juvenal Raimundo da Silva. Não se sabia ao certo nem o nome dele porque recusava-se a falar, não apresentava documentos civis e era louco. Por ter cometido um ato violento, foi confinado em um manicômio psiquiátrico, sob a justificativa de tratamento, e nunca mais voltou à liberdade. Permaneceu na clausura por 46 anos. Essa não é uma história de ficção. É uma história de injustiça analisada Neste livro, que inaugura a coleção Bioética e Saúde. Juvenal foi o homem que mais tempo ficou confinado em um manicômio judiciário no Brasil, abandonado à espera de uma decisão oficial sobre sua experiência, banido do convívio social e do reconhecimento de direitos. Se a Justiça considera 30 anos como pena máxima para prisão, o que aconteceu ali durante todo esse tempo? A autora buscou responder a essa pergunta ao analisar o dossiê de Juvenal, sob a guarda do manicômio judiciário. Ela se debruçou sobre o arquivo para realizar uma análise das práticas discursivas de saber e poder sobre Juvenal. Seu estudo revela o funcionamento “da máquina de abandono que confiscou a existência de Juvenal”.', '["long-term institutionalization","mental illness and criminal responsibility","forensic psychiatry","bioethics"]', '10.7476/9786557082973', '9788575415573', 'https://books.scielo.org/id/z9kn7', 'https://books.scielo.org/id/z9kn7/pdf/brito-9786557082973.pdf', NULL, 'https://books.scielo.org/id/z9kn7/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
