.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-zb2bg', 'zb2bg', 'Clássicos em Doença de Chagas: histórias e perspectivas no centenário da descoberta', NULL, '["José da Rocha Carvalheiro","Azevedo, Nara","Tania C. de (org.) Araújo-Jorge","Joseli Lannes-Vieira","Maria de Nazaré Correia Soeiro","Klein, Lisabel"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Este admirável volume reuniu especialistas de diversos campos do conhecimento para comentar a importância de 15 artigos clássicos associados à descoberta científica de Carlos Chagas, que completou cem anos em 2009. A obra indica novas diretrizes e os desafios que ainda cercam a doença na atualidade. Organizado por pesquisadoras do Instituto Oswaldo Cruz (IOC/Fiocruz) e da Casa de Oswaldo Cruz (COC/Fiocruz), pela coordenadora de eventos da Fiocruz e por um ex-vice-presidente de pesquisa da instituição, que juntos formaram uma rede para definir quais seriam os principais artigos clássicos que demarcaram o avanço das pesquisas sobre doença de Chagas, o livro contextualiza-os em relação ao centenário e "…assim surge…, coletivo, histórico e atual", nas palavras de uma das organizadoras.', '["Chagas disease","Carlos Chagas","history of medicine","Trypanosoma cruzi"]', '10.7476/9786557081013', '9786557081013', 'https://books.scielo.org/id/zb2bg', 'https://books.scielo.org/id/zb2bg/pdf/carvalheiro-9786557081013.pdf', NULL, 'https://books.scielo.org/id/zb2bg/cover/cover_thumbnail.jpeg', NULL, 6, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-zb2gf', 'zb2gf', 'Educação profissional em saúde', NULL, '["Isabel Brasil Pereira","Marise Nogueira Ramos"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2006, '2006-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Health Professions', '1.Educação profissionalizante -tendências.2.Pessoal técnico de saúde/educação.3. Pessoal de saúde/educação.I. Ramos, Marise Nogueira.II.Título.CDD -20.ed', '["health professions education","professionalization","healthcare workers","educational trends"]', '10.7476/9788575413180', '9788575413180', 'https://books.scielo.org/id/zb2gf', 'https://books.scielo.org/id/zb2gf/pdf/pereira-9788575413180.pdf', NULL, 'https://books.scielo.org/id/zb2gf/cover/cover_thumbnail.jpeg', NULL, 19, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-zb6cs', 'zb6cs', 'História da arquitetura e da cidade no Brasil e em Portugal: séculos XVI ao XIX: antologia crítica - Volume 1', 'séculos XVI ao XIX: antologia crítica - Volume 2', '["Clóvis Ramiro Jucá Neto","Rodrigo Espinha Baeta"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2026, '2026-01-01', 'pt', 'book', 'engineering-tech', 'Ingeniería y Tecnología', 'Engineering', 'Esta antologia reúne pesquisadores e pesquisadoras do Brasil e de Portugal em torno de um amplo panorama da produção historiográfica recente sobre arquitetura e cidade entre os séculos XVI e XIX. Ao explorar a circulação de ideias, formas, agentes e saberes no universo português, a obra evidencia as conexões transnacionais que moldaram a arquitetura, o urbanismo e as artes em diferentes contextos locais. Dividido em cinco seções temáticas, o livro aborda desde processos de transculturação e fundação de núcleos urbanos até arquitetura civil, religiosa e formas de representação pictórica e gráfica. As análises revelam a diversidade da arquitetura brasileira e portuguesa, destacando a relação entre cidade, paisagem, poder e cultura material, além de iluminar os intercâmbios que marcaram a constituição da escola barroca e da experiência urbana no mundo luso-brasileiro.', '["architectural history","urban history","colonial Brazil","Portuguese colonialism","transnational cultural exchange","transculturation","city founding","civil architecture","religious architecture","landscape and power","material culture","urban experience"]', '10.7476/9786556309941', '9786556309491', 'https://books.scielo.org/id/zb6cs', 'https://books.scielo.org/id/zb6cs/pdf/juca-9786556309941.pdf', NULL, 'https://books.scielo.org/id/zb6cs/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-zbh7t', 'zbh7t', 'Educação superior nos Estados Unidos: história e estrutura', NULL, '["Reginaldo Carmello Corrêa de Moraes"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Educação superior nos Estados Unidos nos apresenta uma narrativa panorâmica sobre a constituição do sistema educacional de nível superior norte-americano. Rejeitando o caminho da adjetivação infundada, Reginaldo C. Moraes elabora uma cuidadosa análise histórica de uma das principais instituições dos Estados Unidos.', '["higher education","higher education history","higher education structure","universities","United States higher education"]', '10.7476/9788595460423', '9788539305599', 'https://books.scielo.org/id/zbh7t', NULL, NULL, 'https://books.scielo.org/id/zbh7t/cover/cover_thumbnail.jpeg', 236, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-zbt2c', 'zbt2c', 'O (des)aprendizado de si', 'transexualidades, interação e cuidado em saúde', '["Rodrigo Borba"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'Bianca e Leandro formavam um casal. “Bianca exibia um corpo com formas arredondadas decorado por vestidos, maquiagem e saltos altos, mas ainda tinha o pênis; Leandro usava faixas para apertar os seios e uma meia enrolada na cueca para fazer volume nas calças. Uma mulher com pênis; um homem sem? Um menino vira mulher e namora uma menina que vira homem? Ela é ele? Ele é ela?” Do choque inicial veio a motivação para o trabalho de doutorado sobre candidatos/as ao processo transexualizador em um serviço de um hospital público. Nessa pesquisa, o professor da UFRJ Rodrigo Borba encontrou um flagrante descompasso entre o que os serviços de saúde entendem como transexualidade e as variadas formas como as pessoas transexuais efetivamente vivenciam suas identidades no cotidiano. Como consequência, persistem obstáculos discursivos para uma atenção integral e humanizada à saúde de sujeitos transexuais. O autor defende que se reaprenda a cuidar da saúde de sujeitos transexuais, respeitando-os efetivamente como pessoas e valorizando as formas particulares de se vivenciar a transexualidade. Respeitando e valorizando, em especial, “quem podemos ser, para além das normas convencionalizadas sobre nossos corpos: um desafio cotidiano em nossos tempos”, conforme lembra o também professor da UFRJ Luiz Paulo da Moita Lopes, orientador da tese que originou este novo volume da coleção Antropologia & Saúde.', '["transgender people","transgender identity","gender identity","hospital care","gender norms","self-knowledge","medical anthropology"]', '10.7476/9786557082942', '9788575414743', 'https://books.scielo.org/id/zbt2c', 'https://books.scielo.org/id/zbt2c/pdf/borba-9786557082942.pdf', NULL, 'https://books.scielo.org/id/zbt2c/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-zc69f', 'zc69f', 'Entre o medieval e o moderno', 'representações e rupturas, filosofia, cultura e direito', '["Salgado, Karine","Dal Ri Jr., Arno"]', 'Editora UFMG', 'Brasil', 'SciELO Books', 'books', 2025, '2025-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Lançar um olhar sobre o Medievo é uma aventura de desfecho imprevisível. Julgado e condenado pela Modernidade, ele ainda sobrevive no imaginário popular como a Idade das Trevas, em oposição ao período que lhe sobreveio e que dissipou, pela luz da razão, a escuridão. Período desconhecido, remete, perante o senso comum, à introspecção, ao afastamento e ao misterioso. O Medievo, entretanto, está muito distante das imagens que, lamentavelmente vinculadas a ele, mantêm a soberba pretensão de defini-lo. Um olhar mais detido nesse período revela uma riqueza incontrolável e, eventualmente, semelhanças incômodas com nosso tempo. A singularidade e a identidade do Medievo surpreendem não apenas pela sua pujança, mas especialmente pelos incontáveis pontos de contato com nossa realidade ou ainda pelos desdobramentos determinantes para nossa realidade. São justamente as rupturas e continuidades entre o medieval e o moderno que ensejaram a concepção desta obra.', '["Middle Ages","modernity","medievalism","medieval identity"]', '10.7476/9786558582137', '9788542302479', 'https://books.scielo.org/id/zc69f', NULL, NULL, 'https://books.scielo.org/id/zc69f/cover/cover_thumbnail.jpeg', 341, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-zcssy', 'zcssy', 'Promoção da cultura de notificação de incidentes em saúde', NULL, '["Celsa Raquel Villaverde Melgarejo","Patrícia de Carvalho Mastroianni","Fabiana Rossi Varallo"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'O objetivo principal das notificações de incidentes em saúde não é culpabilizar os recursos humanos envolvidos nos erros. Sua função primordial visa ao aprendizado, ou seja, conhecer as fragilidades dos processos e, por conseguinte, desempenhar ações de gerenciamento e mitigação de riscos. Tem, sobretudo, a finalidade de prevenir agravos à condição clínica dos usuários, por causa da caracterização e, até mesmo, dos quase-erros ou near misses. Este livro apresenta uma proposta de educação continuada para programas que visem à implementação da cultura de segurança de pacientes em serviços de saúde, com o intuito de promover habilidades e competências em notificações espontâneas de incidentes em saúde. Trata-se de uma bibliografia complementar, com abordagem multidisciplinar para os cursos de graduação e pós-graduação da área de Farmácia, Enfermagem, Medicina, entre outras especialidades. Um dos objetivos deste livro é contribuir com os programas de educação continuada dos serviços em saúde, em todos os níveis de atenção e complexidade. Autoras: Celsa Raquel Villaverde Melgarejo, Patricia de Carvalho Mastroianni, Fabiana Rossi Varallo.', '["patient safety culture","near misses","patient safety education","continuing education","risk management","medical errors","patient harm prevention","health services"]', '10.7476/9788595463370', '9788595463370', 'https://books.scielo.org/id/zcssy', 'https://books.scielo.org/id/zcssy/pdf/melgarejo-9788595463370.pdf', NULL, 'https://books.scielo.org/id/zcssy/cover/cover_thumbnail.jpeg', NULL, 6, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-zcvh9', 'zcvh9', 'Tecnologia e o mundo da vida: do jardim à terra', NULL, '["Don Ihde"]', 'Editora UFFS', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', '"Tecnologia e o Mundo da Vida: do Jardim à Terra, tradução de Technology and the lifewold: From Gardem to Earth, feita por Maurício Bozatski, trata das relações humano-tecnologia. É uma das mais importantes obras para a filosofia da tecnologia e pós-fenomenologia, escrita originalmente em língua inglesa, em 1990, por Don Ihde. Apesar de ter sido traduzida para várias línguas, ainda não havia tradução em língua portuguesa.Trata-se do trabalho mais sistemático de Don Ihde (1934-). De acordo com o autor, Tecnologia e o Mundo da Vida: do Jardim à Terra nasceu num tempo crucial e com sua ênfase sobre o multiculturalismo, a incorporação e em direção a uma nova práxis na ontologia de inter-relações."', '["Don Ihde","human-technology relations","philosophy of technology","postphenomenology","lifeworld","multiculturalism","praxis"]', '10.7476/9788564905610', '9788564905610', 'https://books.scielo.org/id/zcvh9', 'https://books.scielo.org/id/zcvh9/pdf/ihde-9788564905627.pdf', NULL, 'https://books.scielo.org/id/zcvh9/cover/cover_thumbnail.jpeg', NULL, 8, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-zd6bp', 'zd6bp', 'Resultados maternos y fetales de la actividad física durante el embarazo', NULL, '["Robinson Ramírez‐Vélez","Jorge Enrique Correa‐Bautista"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2015, '2015-01-01', 'es', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Esta obra reúne información relevante y novedosa para el estudio de la actividad física durante la gestación y brinda los lineamientos necesarios para que los profesionales de las ciencias de la salud y los profesionales de las ciencias de la educación física y del deporte puedan promover la actividad física y prescribir y monitorear el ejercicio durante esta etapa del ciclo vital de la mujer. Los autores logran dar respuesta a un vacío conceptual y metodológico sobre la forma de promover la actividad física y el ejercicio, ya que durante muchos años se pensó que eran contraindicados durante la gestación.', '["exercise during pregnancy","maternal outcomes","fetal outcomes","exercise monitoring","physical activity promotion"]', '10.7476/9789587386059', '9789587386042', 'https://books.scielo.org/id/zd6bp', NULL, NULL, 'https://books.scielo.org/id/zd6bp/cover/cover_thumbnail.jpeg', 156, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-zdx9x', 'zdx9x', 'Infância, imagens e vertigens', NULL, '["Bianca Santos Chisté"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O autor explica que, devido à inexistência de uma teoria e crítica específicas desse gênero, o saber escolar que se fundou no âmbito do ensino da literatura infantil passou a “funcionar” como teorização do gênero no período abordado (1947-2003).', '["children''s literature","genre theory","school knowledge","literature teaching","children''s literature didactics","genre criticism"]', '10.7476/9788579837081', '9788579837081', 'https://books.scielo.org/id/zdx9x', 'https://books.scielo.org/id/zdx9x/pdf/chiste-9788579837081.pdf', NULL, 'https://books.scielo.org/id/zdx9x/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-zf48z', 'zf48z', 'De Cuba à Patagônia: desafios da educação militar no terceiro milênio', NULL, '["Suzeley Kalil Mathias","Eduardo Mei","Cláudio de Carvalho Silveira"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro propõe um conjunto de estudos sobre a educação militar na América do Sul, exceto a Guiana Francesa, departamento francês em ultramar. Na América Latina, não há uma entidade que padronize a estrutura política e o modelo de educação militar, como ocorre na União Europeia. Cada país adota formas e normas que acredita serem as mais adequadas para educar seus militares. Nesse contexto latino-americano, dada a constante participação dos militares na política, com a manutenção menor ou maior da autonomia político-institucional das Forças Armadas, nem sempre há conexão entre os sistemas civil e militar de ensino.Todavia, conforme os textos reunidos neste livro exemplificam, a região conheceu, no interior dos processos de transição dos regimes burocrático-autoritários para governos democráticos que marcaram os últimos trinta anos, tentativas, mais ou menos profundas, de maior controle civil sobre a educação militar.', '["military education","Latin America","South America","civil-military relations","military autonomy","democratization","civilian control of the military","Cuba","Patagonia"]', '10.7476/9786557140512', '9786557140512', 'https://books.scielo.org/id/zf48z', 'https://books.scielo.org/id/zf48z/pdf/kalil-9786557140512.pdf', NULL, 'https://books.scielo.org/id/zf48z/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-zffb8', 'zffb8', 'O mundo invisível: cosmologia, sistema ritual e noção de pessoa no espiritismo', NULL, '["María Laura Viveiros de Castro Cavalcanti"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este livro propõe-se a estudar o Espiritismo como um sistema religioso, um sistema de crenças e práticas que se inclui no quadro maior de religiões mediúnicas. Com base na seleção de grupos específicos, seu objetivo central é a apreensão e discussão das categorias e representações que constituem essa experiência religiosa e dos valores culturais a ela relacionados. Nessa perspectiva a percepção da construção da noção de pessoa no Espiritismo se apresenta como um fio condutor e como uma pista particularmente esclarecedora da experiência do transe e da mediunidade nessa religião. [trecho retirado da apresentação do livro]', '["spiritism","cosmology","ritual system","concept of person","trance","mediumship","religious experience","spiritualism"]', '10.7476/9788599662274', '9788599662274', 'https://books.scielo.org/id/zffb8', 'https://books.scielo.org/id/zffb8/pdf/cavalcanti-9788599662274.pdf', NULL, 'https://books.scielo.org/id/zffb8/cover/cover_thumbnail.jpeg', NULL, 30, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-zfkwr', 'zfkwr', 'Semântica cognitiva sócio - histórica: estudos sobre o significado', NULL, '["Neila Maria Oliveira Santana","A. Ariadne Domingues Almeida"]', 'EDUNEB', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro Semântica cognitiva sócio-histórica: estudos sobre o significado, que ora apresentamos, oferece ao(à) seu(ua) leitor(a) resultados de pesquisas que foram elaboradas tendo como norte teórico a Linguística Cognitiva. Concebida como proposta conciliadora para promover estudos sobre a linguagem e como fonte de frutíferos diálogos entre dimensões da vida humana antes separadas, como a cognitiva e a social, a Linguística Cognitiva foi adotada por diferentes pesquisadores.', '["cognitive linguistics","meaning","language and cognition","language and society","history of meaning"]', '10.7476/9786588211342', '9786588211199', 'https://books.scielo.org/id/zfkwr', 'https://books.scielo.org/id/zfkwr/pdf/santana-9786588211342.pdf', 'https://books.scielo.org/id/zfkwr/epub/santana-9786588211342.epub', 'https://books.scielo.org/id/zfkwr/cover/cover_thumbnail.jpeg', 232, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-zfzg5', 'zfzg5', 'Saberes tradicionais e locais: reflexões etnobiológicas', NULL, '["Marcelo Guerra Santos","Mariana Quinteiro"]', 'EDUERJ', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'agricultural-sciences', 'Ciencias Agrícolas y Veterinaria', 'Agricultural and Biological Sciences', 'Durante séculos, diversos conhecimentos elaborados e mantidos por grupos sociais considerados à margem da sociedade receberam a classificação de conhecimento popular e conhecimento vulgar, o que demarcou o distanciamento entre esses saberes e o mundo das ciências. Este livro destaca, sob a perspectiva da etnobiologia, o potencial dos saberes tradicionais na construção de ações sustentáveis, refletindo sobre possíveis benefícios para a sociedade. Os autores oferecem análises e informações sobre a contribuição do conhecimento tradicional para a conservação da biodiversidade, para a segurança alimentar e para a saúde, por meio da utilização das plantas medicinais e de outras práticas nativas. O leitor vai perceber que, em muitos momentos, a imposição do mercado ou de pressões políticas não acarretou necessariamente uma melhoria real na alimentação ou na saúde da maior parte da população, como no exemplo dos problemas decorrentes de uma nutrição baseada em alimentos industrializados', '["traditional knowledge","local knowledge","ethnobiology","popular knowledge","biodiversity conservation","food security","medicinal plants","traditional medicine","sustainable development","processed foods"]', '10.7476/9788575114858', '9788575114858', 'https://books.scielo.org/id/zfzg5', 'https://books.scielo.org/id/zfzg5/pdf/santos-9788575114858.pdf', NULL, 'https://books.scielo.org/id/zfzg5/cover/cover_thumbnail.jpeg', NULL, 15, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-zfzq8', 'zfzq8', 'Filosofía y literatura: la experiencia estética en Estanislao Zuleta', NULL, '["Cristhian Perdigón Lesmes"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2015, '2015-01-01', 'es', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Dos son los principales propósitos de esta investigación: por un lado, dar cuenta de la manera en que Estanislao Zuleta hizo filosofía desde la literatura, y, por otro, destacar como consecuencia principal de un hacer filosófico tan particular la presencia en la obra de Zuleta de una inconclusa teoría estética. En procura de cumplir estos objetivos, tres serán los derroteros a seguir: primero, desde el concepto de Lebenswelt y la noción freudiana de sublimación, justificar la compleja relación que tiene lugar entre vida, literatura y filosofía en el pensador colombiano. Segundo, definir el criticismo de Zuleta desde una lectura de Kant semejante a la de la “ontología del presente” de Foucault para mostrar cómo desde allí la literatura obtiene un privilegiado lugar en la reflexión filosófica de la modernidad. En tercer lugar, ver cómo desde la novela moderna y la lectura cruzada que hace Zuleta de Marx y Freud es posible justificar una noción de experiencia estética según la cual la literatura, como el arte en general, ofrece la posibilidad de reconocer la identidad cultural e individual de forma autónoma y crítica. La construcción de esta noción de experiencia estética atravesará el conjunto de la exposición revelando y articulando paulatinamente el concepto de sublimación de Freud, la estética kantiana, el concepto de transfiguración artística común a Nietzsche y Heidegger y las estrechas relaciones que guardan las nociones de historia y trabajo en Marx con el concepto de elaboración de Freud.', '["Estanislao Zuleta","aesthetics","aesthetic experience","philosophy and literature","lifeworld","sublimation","Sigmund Freud","Immanuel Kant","Michel Foucault","ontology of the present","modern novel","Karl Marx"]', '10.7476/9789587386363', '9789587386356', 'https://books.scielo.org/id/zfzq8', NULL, NULL, 'https://books.scielo.org/id/zfzq8/cover/cover_thumbnail.jpeg', 98, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-zg8vf', 'zg8vf', 'A américa latina: males de origem', NULL, '["Manoel Bomfim"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este livro deriva diretamente do amor de um brasileiro pelo Brasil, da solicitude de um americano pela América. Começou no momento indeterminado em que nasceram esses sentimentos; exprime um pouco o desejo de ver esta pátria feliz, próspera, adiantada e livre. Foram esses sentimentos que me arrastaram o espírito para refletir sobre essas coisas, e o fizeram trabalhar essas ideias – o desejo vivo de conhecer os motivos dos males de que nos queixamos todos. Desse modo, as notações, as analogias, as observações, as reflexões se acumularam.[Trecho retirado da advertência do livro]', '["Latin America","political philosophy","social criticism","Brazil","national prosperity","freedom"]', '10.7476/9788599662786', '9788599662786', 'https://books.scielo.org/id/zg8vf', 'https://static.scielo.org/scielobooks/zg8vf/pdf/bomfim-9788599662786.pdf', NULL, 'https://books.scielo.org/id/zg8vf/cover/cover_thumbnail.jpeg', NULL, 70, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-zh63f', 'zh63f', 'El desplazamiento forzado en Colombia: 10 años de la sentencia T-025 de 2004', NULL, '["María Lucía Torres-Villarreal","Paola Marcela Iregui Parra"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2015, '2015-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'La Universidad del Rosario, por conducto del Observatorio Legislativo y el Grupo de Investigación en Derechos Humanos de la Facultad de Jurisprudencia, en asocio con la Fundación Hanns Seidel, organizaron el IV Concurso Nacional de Semilleros titulado “Democracia y Desplazamiento Forzado: un análisis desde diversas perspectivas”, el cual se realizó en el marco del Foro “El Desplazamiento Forzado en Colombia: 10 años de la Sentencia T-025 de 2004”, buscando analizar el estado actual del desplazamiento en Colombia y qué ha pasado con las órdenes impartidas por la Corte Constitucional hace 10 años; así mismo, el objetivo era reconocer los cambios que han existido en la situación de hecho y de derecho de la población desplazada y cuáles son las nuevas dinámicas que han surgido alrededor de esta problemática y que seguramente no existían cuando la Corte profirió tan importante sentencia. De las ponencias recibidas por parte de las diferentes instituciones educativas del país, fueron seleccionadas doce para participar en la fase oral que se dio cita los días 5 y 6 de agosto de 2014, en la Universidad del Rosario. Estas ponencias daban cuenta, desde distintos escenarios, del estado del desplazamiento forzado en Colombia, tal como se propuso con el Foro, pero desde las perspectivas de los estudiantes, quienes a partir de la investigación formativa analizaron el fenómeno. Tanto la fase oral como la escrita, contaron con la participación de profesores de altas calidades profesionales y académicas que actuaron como pares evaluadores y jurados, certificando así la calidad de las ponencias presentadas y ello los resultados obtenidos. Con este ejercicio pedagógico se observaron los resultados y la importancia de la investigación formativa en las facultades de Derecho y todas las carreras afines, siendo el presente libro una prueba y resultado de ello.', '["forced displacement","internally displaced persons","Colombian Constitutional Court","constitutional order","human rights","Colombia"]', '10.7476/9789587385595', '9789587385595', 'https://books.scielo.org/id/zh63f', 'https://books.scielo.org/id/zh63f/pdf/torres-9789587385595.pdf', NULL, 'https://books.scielo.org/id/zh63f/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-zhfmd', 'zhfmd', 'Poder, hierarquia e reciprocidade: saúde e harmonia entre os Baniwa do Alto Rio Negro', NULL, '["Luíza Garnelo"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2003, '2003-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Resultado de ampla pesquisa na qual a autora apresenta os diversos aspectos que compõem o complexo mundo baniwa, a importância que a doença ocupa nele, suas especificidades, sua cultura, seu modo estóico de vida, suas inter-relações com outros grupos étnicos do Alto Rio Negro, Amazonas. Nos permite mergulhar e melhor compreender o ‘caleidoscópio de problemas vividos hoje pelos povos indígenas’ no Brasil em diversas áreas. Sociopoliticamente de alta relevância, revela a distância entre as necessidades desse povo e os serviços de saúde para eles disponibilizados, pautados por um tendência à uniformização e baixa sensibilidade às diferenças culturais. Transcende o contexto rionegrino, sendo relevante para o universo indígena como um todo. Academicamente instigante e politicamente perspicaz, inaugura nova coleção em grande estilo.', '["Baniwa","Alto Rio Negro","Indigenous health","illness","power","hierarchy","reciprocity","interethnic relations","Amazonian indigenous peoples","health care access"]', '10.7476/9786557080122', '9786557080122', 'https://books.scielo.org/id/zhfmd', 'https://books.scielo.org/id/zhfmd/pdf/garnelo-9786557080122.pdf', NULL, 'https://books.scielo.org/id/zhfmd/cover/cover_thumbnail.jpeg', NULL, 23, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-zhjcx', 'zhjcx', '10necessárias falas: cidade, arquitetura e urbanismo', NULL, '["Antônio Heliodório Lima Sampaio"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'engineering-tech', 'Ingeniería y Tecnología', 'Engineering', 'Esta publicação integra a Coleção do Programa de Pós-Graduação em Arquitetura e Urbanismo da Universidade Federal da Bahia (Coleção PPG-AU FAUFBA), da Editora da Universidade Federal da Bahia (EDUFBA). Consiste em uma coletânea de ensaios acerca de planejamento, arquitetura e urbanismo, estabelecendo relações de totalidade e fragmentos, expondo ideias e percepções do autor, algumas ainda provisórias e abertas ao diálogo com os leitores. O livro vincula-se a uma ideia de totalidade bem diferente da adotada pelo senso comum dos arquitetos e pertence a um tempo atual, registrando um espaço-tempo específico.', '["cities","architecture","urbanism","urban planning","totality","architectural discourse","urban space"]', '10.7476/9788523211516', '9788523211516', 'https://books.scielo.org/id/zhjcx', 'https://books.scielo.org/id/zhjcx/pdf/sampaio-9788523211516.pdf', NULL, 'https://books.scielo.org/id/zhjcx/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-zhpdd', 'zhpdd', 'Justiça como práxis, funcionamentos humanos e saúde', NULL, '["Carlos Dimas Martins Ribeiro"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', '“Esta obra é uma contribuição inestimável para aqueles que estão comprometidos com a resistência ao modelo predador do capital, mas, principalmente, pretendem avançar na construção de uma sociabilidade baseada no resgate da genericidade humana e no convívio sem as marcas destrutivas do modo de produção capitalista, que esgotou todas as suas potencialidades progressistas e hoje só tem contribuído para nos levar à barbárie. Seu autor fortalece essa trincheira e, no seu campo imediato de intervenção, a saúde coletiva e a bioética, procura recrutar homens e mulheres para a luta por uma ordem social que permita a efetiva emancipação da humanidade”. (Rodrigo de Souza Filho, doutor em serviço social, professor da Faculdade de Serviço Social da Universidade Federal de Juiz de Fora).', '["human functioning","health","capitalist mode of production","sociability","collective health","bioethics","social emancipation"]', '10.7476/9786557080726', '9788575415627', 'https://books.scielo.org/id/zhpdd', NULL, NULL, 'https://books.scielo.org/id/zhpdd/cover/cover_thumbnail.jpeg', 233, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-zhwrg', 'zhwrg', 'Ordem pública e segurança individual: política e polícia no sertão de Pernambuco', NULL, '["Jorge Mattar Villela"]', 'Directory of Open access Books (OAPEN Foundation)', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro pretende mostrar, com base em material de arquivo cuja circunscrição histórica é a Primeira República, os modos de combate ao banditismo do sertão de Pernambuco. Demonstra o modo como as reflexões de políticos, juristas e policiais alocaram o sertão como uma região caracterizada pelo atraso, pela ignorância e que deveria ter como alvo um projeto simultaneamente civilizatório e repressivo. Além disso, a documentação aponta diferentes ações e preocupações políticas e policiais segundo uma clivagem essencial para a época: a ordem pública e a segurança individual.', '["public order","personal security","banditry","Pernambuco sertão","First Brazilian Republic","police policy","civilizing mission","repression","political thought","legal thought","regional underdevelopment"]', '10.7476/9788576003182', '9788576003182', 'https://books.scielo.org/id/zhwrg', 'https://books.scielo.org/id/zhwrg/pdf/villela-9788576003182.pdf', NULL, 'https://books.scielo.org/id/zhwrg/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-zhy4d', 'zhy4d', 'A extensão universitária em comunicação para a formação da cidadania', NULL, '["Eliza Bachega Casadei"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A inserção da Extensão Universitária como um dos pilares de sustentação da atividade acadêmica no Brasil resultou de um reposicionamento epistemológico que, ao questionar os métodos tradicionais da produção da ciência e a função social da universidade, valorizou "os contextos de práticas como ponto de partida do conhecimento científico".Tal disposição estava embasada em uma ideia que "derrubava a tese da neutralidade da ciência e assumia a relação entre os saberes de origens diversas como legítimos e necessários.Reconhecia a dimensão política e cultural do conhecimento e de suas formas de produção" (Cunha, 2012).Para Cunha (2012), inclusive, trata-se de uma resposta dada tipicamente por países latino-americanos, na tentativa de responder a demandas de sociedades marcadas por fortes desigualdades sociais.Constitui uma diligência em que se exige que "a universidade, em especial a de natureza pública, tenha responsabilidade com o desenvolvimento social equilibrado, produzindo saberes para a melhoria de vida de toda a população" (Cunha, 2012).Ainda assim, em relação aos outros pilares presentes nas universidades brasileiras, a extensão continua a ocupar uma posição frágil de menor destaque, o que se reflete em menor financiamento de suas práticas e, consequentemente, em menor engajamento dos O livro traz um conjunto de relatos de experiências práticas na área de extensão em comunicação que enfatizam a importância desses projetos na formação dos alunos e na relação universidade-sociedade.', '["university extension","citizenship education","university-society relations","social role of the university","social inequality","public universities","student training"]', '10.7476/9788579837463', '9788579837463', 'https://books.scielo.org/id/zhy4d', 'https://books.scielo.org/id/zhy4d/pdf/casadei-9788579837463.pdf', NULL, 'https://books.scielo.org/id/zhy4d/cover/cover_thumbnail.jpeg', NULL, 9, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-zjf4z', 'zjf4z', 'Frentes de expansão e estrutura agrária: estudo do processo de penetração numa área da transamazônica', NULL, '["Otávio Velho"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O corpo principal deste trabalho foi apresentado em junho de 1970 como dissertação de mestrado ao Programa de Pós-Graduação em Antropologia Social do Departamento de Antropologia, do Museu Nacional da Universidade Federal do Rio de Janeiro.', '["agrarian structure","land colonization","frontier expansion","Transamazon region","land tenure"]', '10.7476/9788599662915', '9788599662915', 'https://books.scielo.org/id/zjf4z', 'https://books.scielo.org/id/zjf4z/pdf/velho-9788599662915.pdf', NULL, 'https://books.scielo.org/id/zjf4z/cover/cover_thumbnail.jpeg', NULL, 66, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-zjnzf', 'zjnzf', 'Vozes à margem: periferias, estética e política', NULL, '["Bertelli, Giordano Barbin","Gabriel Feltrán"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', '[RETIRADO/WITHDRAWN] Vozes à margem, organizado por Giordano Barbin Bertelli, é o segundo volume da Coleção Marginália de Estudos Urbanos, coordenada por Gabriel de Santis Feltran. A coletânea reúne artigos de diversos pesquisadores dedicados à produção cultural das periferias urbanas brasileiras e apresenta ao público a abordagem do tema da(s) linguagem(ns) e da(s) estética(s) produzida(s)/consumida(s) por grupos marginalizados no cenário urbano contemporâneo. Trata-se de enfocar expressões linguísticas, artístico-culturais e estéticas presentes na sociabilidade destes grupos e de atentar para seus múltiplos significados políticos.', '["urban periphery","marginalized communities","urban culture","aesthetics","language","sociability","Brazilian cities","cultural production"]', '10.7476/9786580216192', '9786580216192', 'https://books.scielo.org/id/zjnzf', NULL, NULL, 'https://books.scielo.org/id/zjnzf/cover/cover_thumbnail.jpeg', NULL, 6, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-zjzvj', 'zjzvj', 'Ficção brasileira no século XXI: terceiras leituras', NULL, '["Helena Bonito Couto Pereira"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', '[RETIRADO/WITHDRAWN] Ficção brasileira no século XXI é um livro instigante. De leitura agradável e de interesse amplo, debruça-se, com competência e inventividade, sobre oito escritores brasileiros contemporâneos, consagrados e premiados. O que não é pouco em uma tradição como a nossa, em que não se encontram muitos estudiosos de literatura que encarem o contemporâneo e consigam discuti-lo de forma a dialogar, não apenas com o estudioso e o especialista como também com o leitor comum interessado em literatura. Adriana Lunardi, Alberto Martins, Luiz Ruffato, Michel Laub, Milton Hatoum, Nelson de Oliveira, Ricardo Lísias e Rodrigo Lacerda encontram, por meio da leitura que deles fazem os autores deste livro, novos olhares para suas obras. E, nestes novos olhares, há um convite para novos leitores e leituras renovadas.', '["Brazilian fiction","contemporary Brazilian literature","21st-century literature","literary criticism","Brazilian writers","Luiz Ruffato","Michel Laub","Milton Hatoum","Ricardo Lísias"]', '10.7476/9788582930489', '9788582930489', 'https://books.scielo.org/id/zjzvj', NULL, NULL, 'https://books.scielo.org/id/zjzvj/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-zkn78', 'zkn78', 'O adolescente em conflito com a lei: do ato infracional à execução das medidas socioeducativas', 'do ato infracional à execução das medidas socioeducativas', '["Marcos Antonio Santos Bandeira"]', 'Editus', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Neste livro, o autor faz uma análise dogmática sobre o ato infracional praticado por adolescentes e as respectivas medidas socioeducativas, como respostas sancionatórias adequadas para esse sujeito na peculiar condição de estar em desenvolvimento. Sustenta-se que a medida socioeducativa, para ser eficaz e interromper a trajetória criminosa do adolescente, deve ser preponderantemente pedagógica e emancipatória, aplicada por uma equipe interdisciplinar devidamente capacitada, dentro dos parâmetros da socioeducação constante da Lei nº 12.594/2012, também conhecida como Lei do SINASE.', '["juvenile delinquency","juvenile offenders","socio-educational measures","juvenile justice","teaching methods","emancipatory education","interdisciplinary teams","juvenile development"]', '10.7476/9788574556420', '9786586213843', 'https://books.scielo.org/id/zkn78', NULL, NULL, 'https://books.scielo.org/id/zkn78/cover/cover_thumbnail.jpeg', 224, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-zkp35', 'zkp35', 'A família Asteraceae no Brasil: classificação e diversidade', NULL, '["Nádia Roque","Aristônio Magalhães Teles","Jimi Naoki Nakajima"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'agricultural-sciences', 'Ciencias Agrícolas y Veterinaria', 'Agricultural and Biological Sciences', 'O livro trata de táxons da família Asteraceae, considerada uma das maiores entre as angiospermas. A elevada riqueza, as mudanças na circunscrição de gêneros, bem como na recente classificação em subfamílias e tribos, evidenciam a necessidade de uma bibliografia atualizada. Por tanto, os artigos aqui presentes constam de esforço de botânicos e vários especialistas para desmistificar o senso comum de que os gêneros de Asteraceae são de difícil identificação, contando como base os estudos da primeira dama botânica no Brasil, a doutora Graziela Maciel Barroso (1912-2003), que contribuiu sobremaneira tanto para a formação de importantes sinanterólogos, quanto para o conhecimento e divulgação da família Asteraceae no país, descrevendo gêneros e espécies novas, bem como confeccionando monografias, revisões taxonômicas e trabalhos de flora.', '["Asteraceae","plant taxonomy","floristic diversity","Brazilian flora","genus circumscription","new species description","taxonomic revision"]', '10.7476/9788523219994', '9788523219994', 'https://books.scielo.org/id/zkp35', 'https://books.scielo.org/id/zkp35/pdf/roque-9788523219994.pdf', NULL, 'https://books.scielo.org/id/zkp35/cover/cover_thumbnail.jpeg', NULL, 18, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-zmwwx', 'zmwwx', 'Deus e o diabo no humor das mulheres: contos, casos e crônicas com humor escritos por mulheres', NULL, '["Alba Valeria Tinoco Alves Silva"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'o que é, ent ão nu nca va i saber 49 A mulher e o humor: a p ed r a de Sí si fo não c r ia l i mo 10 1 Por que, como e de que r iem as mulheres da ant olog ia? 169 A nt olog ia v ir t ual de cont os, casos e c rôn icas, com humor, esc r it os por mulheres no Brasil 17 7 Consideraçõ es f inais ou a l ição de Peque na F lor 185 Referênc ias 7 Apresentação Tenho o prazer de compartilhar com você um trabalho original, compilado a partir da tese de doutorado desta autora, que nos propicia uma reflexão sobre o lugar da mulher na nossa sociedade, a partir de sua produção literária pelo viés do humor e da comicidade.Na verdade, pelo acurado trabalho de pesquisa, mesmo com todas as dificuldades que encontrou com a lacuna de registros dessa produção em antologias e publicações especializadas, assim como de material teórico a esse respeito, a nossa autora faz uma apresentação e tece considerações sobre o binômio mulher/humor de maneira rica e consistente, sob óticas diversas do pensamento como a psicanalítica, a filosófica, a antropológica, a sociológica e a linguística, e também a feminina, atestando o fato de que a mulher tem humor e o produz de diversas formas.Com este trabalho ela espelha, mais uma vez, a tradição machista de nossa sociedade, que, a partir de premissas diversas, afirma a exclusividade dessa forma de expressão ao gênero masculino.Se pensarmos no lugar da mulher nas diferentes sociedades através dos tempos, veremos que, por sua posição muitas vezes oprimida e socialmente limitada, encontraríamos dificuldades para encontrar um registro expressivo desse tipo de produção, independentemente de outras, já que isso afrontaria diretamente o status masculino, especialmente com o foco em questão, que tem por característica comum a crítica a si próprio e ao entorno.Tolo foi, e ainda é, o pensamento de que a mulher não tem humor, posto que, pela mesma situação anterior, a mulher teve um lugar especial de observação da sociedade através desses mesmos tempos, que certamente foi criticada com muito humor e transformada em piada por elas, pena que de forma íntima ou muito circunscrita, pois perdemos um rico conteúdo, que, publicado, enriqueceria a produção da humanidade em suas diferentes formas e meios.Eu mesmo queria ter sido uma mosca, muito longeva naturalmente, para poder ter sido testemunha dessas produções privadas, rindo muito à socapa.Nossa muito bem humorada autora, e você poderá ver esse traço, mesmo que de forma leve, na sua escrita, traz uma contribuição particular com essa publicação, fazendo compor aquela lacuna que apontamos anteriormente, trazendo à luz nesse primeiro momento cerca de 20 textos de autoras distintas, embora tenha coletado outras tantas dezenas de obras de origem feminina sobre o humor e com base nele, que não coube nesse primeiro momento de estudo e pesquisa sobre o tema em questão.Esperemos novas produções sobre esse tema e com base nele por parte dela, e teremos, além de pensadora, mais uma artista do humor na literatura brasileira, passando a fazer parte dessa lista.Ainda sobre a malfadada afirmação de que a mulher não tem humor, não sei se rio disso ou com isso, para aliviar o sofrimento da comprovação de mais essa competência, digamos, da representação feminina na nossa medíocre existência.O fato é que o que foi enunciado desabona o pretenso mundo humorístico masculino, já que isso não tem graça nenhuma, além do que esse trabalho é prova cabal.Enquanto o homem busca na religião uma forma de suportar a dor de sua existência, o humor é justamente o remédio para lidar com isso, creio ser a fórmula essencial de salvação descoberta no grande laboratório da humanidade. Fernando Marinho Carnaval de 2014 9 IntroduçãoNa introdução de seu livro Os humores da língua, Sírio Possenti 1 diz que acha difícil que se possa acrescentar algo interessante ao que já foi dito sobre o humor, principalmente sobre os chistes ou a piada, a menos que se descubra um novo ângulo de análise sobre o assunto.Ele acrescenta, contudo, que ainda há questões a serem abordadas nesse campo, entre as quais ele inclui a sugestão feita por Millôr Fernandes 2 a teólogos, psicólogos, antropólogos de que se estude a ocorrência de piadas em grupos discriminados.É possível que o tema deste livro esteja alinhado, ao mesmo tempo, com a reflexão de Possenti e com a sugestão de Millôr, pois o que se pergunta aqui é por que a participação das mulheres na produção de textos de humor no Brasil parece tão insignificante.Essa afirmação baseia-se em obras de referência sobre o humor, publicadas entre 1969 e 2012, nas quais os nomes de mulheres nunca ultrapassam 5% do total de autores.Em antologias de contos não humorísticos, o percentual de mulheres é mais significativo do que aquele apresentado para os textos de humor.Tomando como exemplo a antologia Os cem melhores contos brasileiros do século, organizada por Italo Moriconi 3 , nela são arrolados 1 POSSENTI, S. Os humores da língua: análises linguísticas de piadas.', '["women''s humor","women writers","women''s writing","gender and humor","machismo","women''s status","Brazilian women''s literature","short stories","case studies","chronicles","women''s equality"]', '10.7476/9788523218683', '9788523218683', 'https://books.scielo.org/id/zmwwx', 'https://books.scielo.org/id/zmwwx/pdf/silva-9788523218683.pdf', NULL, 'https://books.scielo.org/id/zmwwx/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-zn6c5', 'zn6c5', 'Dança na cultura digital', NULL, '["Ivani Santana"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2006, '2006-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'É impossível pensar o ser humano contemporâneo se não imerso em um ambiente naturalmente híbrido: biológico e tecnológico em constante interação. É esse o convite que o trabalho de Ivani nos faz, observar o corpo dançando ao sabor da tecnologia, numa metáfora para essa relação. O título é um dos primeiros livros sobre o tema lançado pela Editora.', '["dance","digital culture","body and technology","human-technology interaction","dance and technology"]', '10.7476/9788523209056', '9788523209056', 'https://books.scielo.org/id/zn6c5', 'https://books.scielo.org/id/zn6c5/pdf/santana-9788523209056.pdf', NULL, 'https://books.scielo.org/id/zn6c5/cover/cover_thumbnail.jpeg', NULL, 11, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-zngnn', 'zngnn', 'Foundations of Paleoparasitology', NULL, '["Ferreira, Luiz Fernando","Karl Jan Reinhard","Adauto Araújo"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2014, '2014-01-01', 'en', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Unprecedented initiative in the world, the book compiles the available knowledge on the subject and presents the state-of-the-art in paleoparasitology – term coined about 30 years ago by Brazilian Fiocruz researcher Luiz Fernando Ferreira, pioneer in this science which is concerned with the study of parasites in the past. Multidisciplinary by essence, paleoparasitology gathers contributions from social scientists, biologists, historians, archaeologists, pharmacists, doctors and many other professionals, either in biomedical or humanities fields. With varied applications such as in evolutionary or migration studies, their results often depend on the association between laboratory findings and cultural remains. The book is divided into four parts - Parasites, Hosts, and Human Environment; Parasites Remains Preserved in Various Materials and Techniques in Microscopy and Molecular Diagnostics; Parasite Findings in Archeological Remains: a paleographic view; and Special Studies and Perspectives. Signed by authors from various countries such as Argentina, USA, Germany and France, the book has chapters devoted to the discoveries of paleoparasitology on all continents.', '["paleoparasitology","paleopathology"]', '10.7476/9788575415986', '9788575415986', 'https://books.scielo.org/id/zngnn', 'https://books.scielo.org/id/zngnn/pdf/araujo-9788575415986.pdf', NULL, 'https://books.scielo.org/id/zngnn/cover/cover_thumbnail.jpeg', NULL, 51, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-zngyg', 'zngyg', 'Sistemas de saúde: continuidades e mudanças', NULL, '["Paulo Marchiori Buss","María Eliana Labra"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 1995, '1995-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Reúne o pensamento e as análises de especialistas sobre as reformas contemporâneas nos sistemas de saúde da Argentina, Brasil, Chile, Espanha, Estados Unidos, México e do Québec. Saúde como componente essencial do Estado de Bem-Estar Social, universalidade e eqüidade, estrutura de financiamento do sistema, elevação dos custos da assistência médica, privatização do setor, representação dos interesses de atores sociais, são alguns dos temas evocados. Os artigos permitem uma visão comparativa dos vários e o bom (ou mau) desenlace das propostas de mudanças em curso. Ótima oportunidade para cotejar as experiências desses países, simultaneamente tão próximos e tão díspares entre si, num momento em que estão em xeque o modelo tradicional centralizado e em construção novas formas descentralizadas de organização.', '["health care reform","health care financing","health care costs","health care privatization","welfare state","health equity","universal health coverage","comparative health policy","Argentina","Brazil","Chile","Mexico"]', '10.7476/9788575414026', '9788575414026', 'https://books.scielo.org/id/zngyg', 'https://static.scielo.org/scielobooks/zngyg/pdf/buss-9788575414026.pdf', NULL, 'https://books.scielo.org/id/zngyg/cover/cover_thumbnail.jpeg', NULL, 13, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-znknr', 'znknr', 'Pesquisas no ensino de ciências: reflexões sobre currículo e formação de professores', NULL, '["Lopes, Eduarda da Silva","Santos, Rosemar Ayres dos","Sandra Maria Wirzbicki"]', 'Editora UFFS', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', '“Pesquisas no Ensino de Ciências: reflexões sobre currículo e formação de professores” sinaliza o compromisso dos pesquisadores e das pesquisadoras – mestrandos(as) e professores(as) permanentes e colaboradores do Programa de Pós-Graduação em Ensino de Ciências (PPGEC) – com a construção coletiva de conhecimentos na área de Ensino de Ciências. Organizado em duas seções – 1) Políticas educacionais e currículo e 2) Formação de professores e práticas pedagógicas –, o livro tem quatorze capítulos, que envolvem a participação de vinte e oito autores e autoras, todos(as) envolvidos com a segunda turma de Mestrado do PPGEC. Os textos que o constituem são resultados de pesquisas na área do Ensino de Ciências vinculadas ao curso de extensão Ciclos Formativos para o Ensino de Ciências e Matemática, realizado desde 2010 na UFFS Campus Cerro Largo (RS), com encontros que sistematizam processos de formação e têm como público professores em formação inicial e continuada, e aos seguintes grupos: Grupo de Estudos e Pesquisa no Ensino de Ciências (GEPECIEM); Grupo de Pesquisa em Educação em Ciências Naturais (GPECieN); Grupo de Investigações em Ciência, Educação e Tecnologia (GICET); Grupo de Pesquisa em Filosofia, Literatura e Artes na Educação (GPHILIA); Grupo de Estudos e Pesquisa em Políticas Educacionais e Práticas Pedagógicas (GEPPEPP) da UFFS. Trata-se do quarto volume da Coleção Ensino de Ciências, organizada pelos pesquisadores Roque Ismael da Costa Güllich, Rosangela Inês Matos Uhmann e Rosemar Ayres dos Santos.', '["science education","course program","teacher professional development","education policy","teaching practice","initial and continuing teacher education","science teacher education","mathematics teacher education","collective knowledge construction"]', '10.7476/9786550190637', '9786550190637', 'https://books.scielo.org/id/znknr', 'https://books.scielo.org/id/znknr/pdf/lopes-9786550190637.pdf', NULL, 'https://books.scielo.org/id/znknr/cover/cover_thumbnail.jpeg', NULL, 5, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-znwtr', 'znwtr', 'Ao correr da pena (folhetins inéditos)', NULL, '["José de Alencar"]', 'EdUFSCar', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O livro Ao correr da pena (folhetins inéditos), de José de Alencar, apresenta oito folhetins inéditos do romancista romântico. Os textos, publicados inicialmente no jornal Correio Mercantil, entre setembro de 1854 e julho de 1855, não aparecem na fortuna literária do autor, sendo, a rigor, textos inéditos, já que, até hoje, além de nunca estudados, nunca tinham sido recolhidos em livro. Além dos folhetins, o livro é aberto pelo ensaio “O enigma dos folhetins”, de Wilton José Marques, que levanta algumas questões sobre o porquê de os textos não terem sido anteriormente publicados.', '["José de Alencar","unpublished short stories","Brazilian Romanticism"]', '10.7476/9786580216116', '9786580216116', 'https://books.scielo.org/id/znwtr', 'https://books.scielo.org/id/znwtr/pdf/alencar-9786580216116.pdf', NULL, 'https://books.scielo.org/id/znwtr/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-zp5mb', 'zp5mb', 'O museu paulista', NULL, '["Ana Cláudia Fonseca Brefe"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2005, '2005-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Obra que retrata o Museu Paulista (conhecido como Museu do Ipiranga), a partir de sua construção, em fins do século XIX, como depositário da memória nacional atrelada à paulista, construída por meio da epopéia bandeirante e da vocação desbravadora paulista, desde os tempos coloniais e materializada em objetos, documentos e iconografia, numa narrativa cuja pertinência das análises e profundidade da pesquisa tornam o livro fundamental para os estudos sobre a disciplina História, conforme definida na ocasião e nas décadas iniciais do século XX. Resgata a figura de Affonso d''Escragnolle Taunay, quem literalmente forjou a vocação histórica do Museu Paulista durante sua atuação como diretor entre 1917 e 1939, dando lógica e ordenamento à coleção de objetos históricos espalhados pelo prédio anteriormente, separando o objetivo inicial de dedicação às ciências naturais e à exposição de exemplares da fauna e da flora brasileiras. (Co-edição: Museu Paulista)', '["Museu Paulista","national memory","bandeirantes","colonial Brazil","museum history","history as a discipline","historical collections","natural history collections","iconography","São Paulo"]', '10.7476/9788539303281', '9788571395886', 'https://books.scielo.org/id/zp5mb', NULL, NULL, 'https://books.scielo.org/id/zp5mb/cover/cover_thumbnail.jpeg', 336, 47, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-zpbsx', 'zpbsx', 'Construções subordinadas na lusofonia: uma abordagem discursivo-funcional', NULL, '["Erotilde Goreti Pezatti"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Erotilde Goreti Pezatti*A abordagem teórica aqui adotada busca construir um "modelo" do usuário de língua natural, observando como falantes e ouvintes têm sucesso na comunicação uns com os outros por meio do uso de expressões linguísticas.Entende-se aqui, com base em Dik (1989), que a interação verbal -ou seja, a interação social por meio da língua -é uma forma de atividade cooperativa estruturada.É cooperativa porque necessita de pelo menos dois participantes para atingir seu objetivo, e é estruturada (e não aleatória) porque é governada por regras, normas e convenções.Na interação verbal, os participantes se servem de certos instrumentos que, no sentido geral do termo, são chamados de "expressões linguísticas".Estas expressões são elas mesmas entidades estruturadas, isto é, são governadas por regras e princípios de dois tipos, ambos ratificados pela convenção social:1) as regras que governam a constituição das expressões linguísticas (regras semânticas, sintáticas, morfológicas e fonológicas);', '["verbal interaction","language expression","collaborative interaction","social conventions"]', '10.7476/9788568334805', '9788568334805', 'https://books.scielo.org/id/zpbsx', 'https://books.scielo.org/id/zpbsx/pdf/pezatti-9788568334805.pdf', NULL, 'https://books.scielo.org/id/zpbsx/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-zpprq', 'zpprq', 'Diálogos para uma educação antirracista', NULL, '["Barzano, Marco Antonio Leandro","Sampaio, Maria Cristina de Jesus"]', 'UEFS Editora', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'As pessoas que propõem o diálogo deste livro, são egressas do Programa de Pós Graduação em Educação da Universidade Estadual de Feira de Santana. Elas, enquanto educadoras, também compartilham de um sonho: uma educação antirracista. Não estão a brincar os autores e autoras e também não nos oferecem apenas palavras doces a acalantar o status quo racial da sociedade brasileira que se acostumou com a ideia de que descendentes de africanos e de indígenas devem ser subalternizados. Além da crítica, seguem com propostas, subversões da linguagem e explicitação de fatos ocultados sobre as condições que os nossos e as nossas vivenciam cotidianamente no ambiente escolar, nas festas populares, nos presídios.', '["anti-racist education","racism in Brazil","racial subordination","indigenous peoples","subversion of language","hidden history","school environment","popular festivals","prisons"]', '10.7476/9788555921209', '9786589524526', 'https://books.scielo.org/id/zpprq', NULL, NULL, 'https://books.scielo.org/id/zpprq/cover/cover_thumbnail.jpeg', 274, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-zpwyf', 'zpwyf', 'Interfaces: representações socioespaciais, geotecnologias e formação de professores', NULL, '["Natanael Reis Bomfim","Silvia Letícia Costa Pereira Correia"]', 'Directory of Open access Books (OAPEN Foundation)', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro busca apreender as representações socioespaciais das professoras da Escola Municipal Álvaro da Franca Rocha sobre o bairro da Engomadeira, em Salvador (BA), a fim de construir um portfólio sobre a memória e identidade do bairro e da Escola.', '["socio-spatial representations","geotechnologies","teacher professional development","school memories","neighborhood identity","urban interface","Salvador, Bahia"]', '10.7476/9786586213102', '9786586213102', 'https://books.scielo.org/id/zpwyf', 'https://books.scielo.org/id/zpwyf/pdf/bomfim-9786586213102.pdf', NULL, 'https://books.scielo.org/id/zpwyf/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-zq6vb', 'zq6vb', 'Estudos de Utilização de Medicamentos: noções básicas', NULL, '["Cláudia Garcia Serpa Osorio-de-Castro"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2000, '2000-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Economics, Econometrics and Finance', 'BIBLIOGRÁFICAS 81 PREFÁCIONa história recente do Brasil, a questão dos medicamentos nunca esteve tão presente nas agendas do setor saúde das três esferas de governo que compõem o SUS.Tampouco esteve tão presente no dia-a-dia do cidadão, invadindo os orçamentos familiares, obrigando a decisões quanto à utilização de determinados medicamentos indispensáveis à preservação da saúde.Assistimos a reajustes vertiginosos de preços em medicamentos de uso contínuo, à instalação de mais uma CPI, a denúncias de falsificação de medicamentos, cartéis, monopólios e oligopólios, dumping, ao acirramento do processo de nossa dependência nos processos farmoquímicos, aos conflitos e aos jogos de interesse presentes nesse setor de tão elevada complexidade e interdisciplinaridade, com interesses cada vez distantes dos da população.Nesse contexto, não apenas no Brasil, torna-se necessário que decisões e ações governamentais sejam respaldadas por embasamentos técnicos, estu¬ dos-piloto, indicadores de avaliação e outras modalidades presentes no exercício acadêmico.De um modo acessível e coerente, os autores ressaltam acertadamente a importβncia dos EUM, a importβncia de estratégias diferenciadas para promover listas de medicamentos essenciais e de formulários terapêuticos como instrumentos que levem ao uso racional dos medicamentos colocados nos serviços de saúde.A importβncia destas estratégias nos países em desenvolvimento e uma análise no contexto brasileiro complementam os aspectos gerais discutidos nos primeiros capítulos.Todos os caminhos da assistência farmacêutica e da política nacional de medicamentos apontam para a necessidade de sua inserção radical nas ações de saúde, para a otimização de recursos e, em especial, para a necessidade de implementar medidas objetivando promover, nos serviços de saúde, o uso racional de medicamentos.Estudos qualitativos e quantitativos abordando consumo de medicamentos são revistos pelos autores, confrontando a adequação e aplicabilidade dos mesmos diante das realidades e necessidades dos serviços de saúdes.Discutem-se, também, aspectos metodológicos, práticos e sua adequação frente a distintas realidades.Entretanto, em todos os momentos, fica claro que os objetivos a alcançar estão centrados na busca pela qualidade na assistência à saúde e na inserção do papel do farmacêutico nesta luta permanente, que, em última instβncia, consiste em viabilizar o modelo de atenção que assegure a saúde como direito de todos.Farmacoepidemiologia e farmacovigilβncia, que incluem aspectos como perfil de segurança, são disciplinas que temos de incorporar à prática cotidiana.Estudos experimentais e ensaios clínicos controlados cada vez mais devem se contrapor ao "esforço incansável da indústria que investe de maneira maciça em propaganda para vender o produto".São as regras do capitalismo: o mercado atua como regulador da oferta e da demanda, ao passo que o sistema de farmacovigilβncia, as reações adversas aos medicamentos são sempre relegados a planos de interesses secundários.Independente de se tratar de estudos quantitativos, estes metodo¬ logicamente simples, ou estudos qualitativos, os autores concluem que a força que têm reside na grande variedade e que sua função sanitária está mais do que justificada.Os EUM precisam não apenas ser mais bem conhecidos e divulgados em relação a fundamentação e paradigma, mas, sobretudo, é preciso que a leitura deste livro incentive unidades acadêmicas e serviços de saúde a iniciarem pequenos estudos de caráter local.Desta maneira, estaremos todos contribuindo para evidenciar o papel dos medicamentos como insumos necessários às ações de saúde, racionalizando', '["drug utilization studies","rational drug use","essential medicines list","therapeutic formulation","pharmaceutical care","national drug policy","health services","drug use","drug prices","drug counterfeiting","developing countries","pilot study"]', '10.7476/9788575412657', '9788575412657', 'https://books.scielo.org/id/zq6vb', 'https://books.scielo.org/id/zq6vb/pdf/castro-9788575412657.pdf', NULL, 'https://books.scielo.org/id/zq6vb/cover/cover_thumbnail.jpeg', NULL, 29, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-zq8t6', 'zq8t6', 'Saberes docentes para a inclusão do aluno com deficiência visual em aulas de física', NULL, '["Éder Pires de Camargo"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A inclusão escolar de alunos com deficiência impõe-se como tema a ser pesquisado para propor práticas adequadas à nova realidade educacional. Alunos com deficiência visual, por exemplo, começaram a frequentar espaços sociais como a escola sem que antigos paradigmas de normalização de comportamentos tenham sido revistos. Neste livro, Eder Pires de Camargo analisa os saberes que professores do ensino médio devem mobilizar para incluir alunos com deficiência visual em atividades de ensino. Toma como exemplo a interessante experiência de uma disciplina de graduação – Prática de Ensino – na qual futuros licenciados estruturaram e implementaram novas práticas de ensino para turmas mistas. A originalidade e contribuição deste trabalho está em propor atividades desenvolvidas por futuros professores e avaliá-las durante os cursos de licenciatura.', '["teacher knowledge","inclusive education","visual impairment","students with disabilities","physics education","secondary schools","teacher professional development","teaching practicum","mixed classrooms","normalization of behavior","disability in schools"]', '10.7476/9788539303533', '9788539303533', 'https://books.scielo.org/id/zq8t6', 'https://books.scielo.org/id/zq8t6/pdf/camargo-9788539303533.pdf', NULL, 'https://books.scielo.org/id/zq8t6/cover/cover_thumbnail.jpeg', NULL, 22, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-zqdnb', 'zqdnb', 'Aspectos técnicos da cultura da romãzeira', NULL, '["Lima, Cláudia Simone Madruga","Rosa, Gabriela Gerhardt da","Bonome, Lisandro Tomas da Silva"]', 'Editora UFFS', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'agricultural-sciences', 'Ciencias Agrícolas y Veterinaria', 'Agricultural and Biological Sciences', '"Aspectos técnicos da cultura da romãzeira", ao longo de seus oito capítulos, reúne informações de pesquisadores, estudantes, produtores e admiradores da cultura da romãzeira, tanto nacionais como internacionais. A obra, que aborda pontos gerais da fruta, técnicas de plantio, manejo, pragas, doenças, colheita e pós-colheita de romãzeira, objetiva difundir os conhecimentos referentes aos aspectos técnicos da cultura. Disponibiliza, aos produtores, estudantes e profissionais, as informações necessárias para viabilizar o cultivo da romãzeira. É leitura indispensável para produtores, pesquisadores, estudantes da graduação e pós-graduação da área das Agrárias, assim como público em geral que tem interesse e curiosidade sobre o assunto.', '["Annona muricata","fruit growing","planting methods","crop management","pests and diseases","harvesting","postharvest handling"]', '10.7476/9786586545821', '9786586545821', 'https://books.scielo.org/id/zqdnb', 'https://books.scielo.org/id/zqdnb/pdf/lima-9786586545821.pdf', NULL, 'https://books.scielo.org/id/zqdnb/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-zqscq', 'zqscq', 'Por uma filosofia empírica da atenção à saúde: olhares sobre o campo biomédico', NULL, '["Kenneth Rochel de Camargo","Maria Inês Nogueira"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'As metodologias qualitativas, largamente usadas pelas ciências sociais, podem contribuir para a compreensão de aspectos singulares e subjetivos da atenção à saúde e da biomedicina. O volume em questão reúne contribuições de um grupo da pós-graduação em saúde coletiva do Instituto de Medicina Social (IMS) da Uerj que defende essa abordagem para a pesquisa em atenção à saúde. “A possibilidade de aprendizado com antigos saberes médicos,... como proposta de uma revitalização paradigmática, surge de forma instigante e provocadora, suscitando novas reflexões e debates”. Nesse contexto, o livro apresenta: trabalhos de cunho etnográfico - investigações no processo de ensino-aprendizagem na acupuntura -, por meio da observação de aulas teóricas e práticas; experiências dos residentes de medicina na atenção às complexas necessidades das pessoas vivendo com HIV/Aids; a relação dos médicos com pacientes que sofrem de sintomas indefinidos; e o cotidiano de uma família que cuida de um parente com múltiplas necessidades, após sua alta hospitalar, entre outras perspectivas da atenção à saúde sob um outro olhar.', '["health care","biomedicine","qualitative research","medical education","medical residents","HIV care","physician-patient relationship","family caregiving","hospital discharge"]', '10.7476/9788575413517', '9788575411735', 'https://books.scielo.org/id/zqscq', NULL, NULL, 'https://books.scielo.org/id/zqscq/cover/cover_thumbnail.jpeg', 228, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-zr6tm', 'zr6tm', 'Linha vermelha: a guerra da Ucrânia e as relações internacionais do século XXI', NULL, '["Loureiro, Felipe"]', 'Editora da Unicamp', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro reúne análises de pesquisadores brasileiros e estrangeiros sobre a guerra iniciada pela Rússia contra a Ucrânia em fevereiro de 2022, discutindo as causas e a natureza do conflito, além de seus impactos para as relações internacionais no século XXI. A partir de múltiplas perspectivas teóricas, a obra reflete sobre temas diversos, entre os quais as razões que levaram a Rússia a invadir a Ucrânia, as características das operações militares no conflito, os efeitos humanitários da guerra, e a questão da responsabilização criminal internacional de atores envolvidos. A obra conta ainda com um conjunto de capítulos focados na posição de países do Sul Global em face da invasão russa, além de uma parte inteira dedicada às perspectivas de longo prazo abertas pelo conflito no sistema internacional, com destaque para os âmbitos da segurança internacional, da economia política internacional e das relações China-EUA e Rússia-EUA.', '["Russian invasion of Ukraine","causes of war","military operations","international criminal responsibility","Global South","international security","international political economy","US-China relations","US-Russia relations"]', '10.7476/9788526816459', '9788526815650', 'https://books.scielo.org/id/zr6tm', NULL, NULL, 'https://books.scielo.org/id/zr6tm/cover/cover_thumbnail.jpeg', 379, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-zrsf8', 'zrsf8', '25 anos de Clínica de Linguagem: um traçado, novas perspectivas', 'um traçado, novas perspectivas', '["Melissa Catrini","Maria Francisca Lier-DeVitto","Lúcia Arantes","Juliana Ferreira Marcolino-Galli","Ana Augusta Monteiro"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2025, '2025-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'Este livro contém um conjunto de trabalhos que desenvolve reflexões teórico-clínicas originais relativas ao diagnóstico e tratamento de crianças, adultos e idosos com queixas de problemas/sintomas na fala. As discussões, relevantes e atuais, interessam não só à Clínica de Linguagem, mas também a outros campos: Fonoaudiologia, Linguística, Educação, Psicologia e Psicanálise. Com esta obra, comemoram-se 25 anos da construção de um pensamento clínico importante.', '["speech disorders","language disorders","speech therapy","diagnosis","children","adults","older adults","psychoanalysis","linguistics","education","history of speech therapy"]', '10.7476/9786556309323', '9786556308289', 'https://books.scielo.org/id/zrsf8', 'https://books.scielo.org/id/zrsf8/pdf/catrini-9786556309323.pdf', NULL, 'https://books.scielo.org/id/zrsf8/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-zrvn9', 'zrvn9', 'A questão social e política no Brasil', NULL, '["Rui Barbosa"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Querem-se fundar a onipotência real do Executivo, escudada na aparente onipotência do congresso, principiem por abolir virtual mente a Constituição, fechando os tribunais. Mais vale acabá-los do que desonrá-los, convertendo-os em rabadilha do poder irresponsável. Se as armas não se inclinarem à justiça, ao menos que a justiça não seja a cortesã das armas. Estas não precisam dela, e, dispensando-lhes os serviços, poupariam, ao menos, a última das degradações morais a um povo resignado ao aniquilamento.', '["executive power","judicial independence","constitution","political crisis","social question","political responsibility","Brazil"]', '10.7476/9788579820748', '9788579820748', 'https://books.scielo.org/id/zrvn9', 'https://static.scielo.org/scielobooks/zrvn9/pdf/barbosa-9788579820748.pdf', NULL, 'https://books.scielo.org/id/zrvn9/cover/cover_thumbnail.jpeg', NULL, 5, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-zrwqd', 'zrwqd', 'As conferências do Cassino em periódicos-fontes primárias e história literária', 'coletânea', '["Rosane Gazolla Alves Feitosa"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'As Conferências do Cassino Lisbonense, realizadas entre maio e junho de 1871, constituem-se como parte de um projeto de intervenção cultural, política, social que a chamada Geração de 70 - integrada por Antero de Quental, Eça de Queirós, Jaime Batalha Reis, Oliveira Martins, Rafael Bordalo Pinheiro, Guerra Junqueiro, Ramalho Ortigão, entre outros jovens intelectuais portugueses - pretendia realizar na sociedade portuguesa no último quartel do século XIX. Por meio do resgate de fontes primárias, jornais da época (1871) - tais como Revolução de Setembro, Diário de Notícias, Jornal da Noite, Diário Popular, Jornal do Comércio, O Partido Constituinte, O Bem Público, A Nação, em formato de microfilmes adquiridos da Biblioteca Nacional de Portugal -, os leitores terão acesso aos textos originais de reportagens escritas no calor da hora em que ocorreram as conferências e poderão avaliar o que foi veiculado naquele momento histórico. Na medida em que o jornal pode aumentar a compreensão de fatores contextuais, os leitores também podem tirar suas próprias conclusões a respeito desse evento importante para a história da literatura portuguesa, do realismo-naturalismo português e da Geração de 70.', '["Generation of ''70","Portuguese literature","literary realism","naturalism","media coverage","Antero de Quental","Eça de Queirós","Guerra Junqueiro","Ramalho Ortigão","Oliveira Martins","cultural intervention"]', '10.7476/9786557144503', '9786557144503', 'https://books.scielo.org/id/zrwqd', 'https://books.scielo.org/id/zrwqd/pdf/feitosa-9786557144503.pdf', NULL, 'https://books.scielo.org/id/zrwqd/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-zry7t', 'zry7t', 'Elementos de transposição: diversidade, evolução, aplicações e impacto nos genomas dos seres vivos', NULL, '["Cláudia M. A. Carareto","Cláudia Barros Monteiro-Vitorello","Marie‐Anne Van Sluys"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Biochemistry, Genetics and Molecular Biology', 'Este livro representa um projeto desafiador: o estudo de sequências genéticas repetidas que são capazes de se mover, tornando os genomas dinâmicos e flexíveis. Os elementos de transposição (TEs) têm a capacidade de se multiplicar e mudar de lugar no genoma, levar consigo genes, promover rearranjos cromossômicos e alterar a expressão de genes vizinhos. Trata-se de um dos tópicos mais instigantes na área da genética, que durante décadas não recebeu o devido reconhecimento. O livro surgiu de uma reunião de integrantes do grupo de pesquisa ''Elementos de Transposição como Agentes de Diversidade'', do CNPq, que consideram indispensável disponibilizar a pesquisadores e estudantes informações que permitam compreender a dinâmica e a plasticidade dos genomas em decorrência da presença dos TEs. “O livro não esgota as inúmeras informações e implicações decorrentes da interação genoma-TE mas propicia aos leitores o contato atualizado e a compreensão dos principais temas relacionados à estrutura e funcionamento dessas sequências genéticas móveis e sua relação com a evolução dos organismos”, afirmam as organizadoras.', '["transposable elements","mobile genetic elements","genome plasticity","genome rearrangement","chromosomal rearrangements","gene expression regulation","genome evolution","genetic diversity"]', '10.7476/9788575415672', '9788575414620', 'https://books.scielo.org/id/zry7t', NULL, NULL, 'https://books.scielo.org/id/zry7t/cover/cover_thumbnail.jpeg', 196, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-zs425', 'zs425', 'Estação etnográfica Bahia: a construção transnacional dos Estudos Afro-brasileiros (1935-1967)', NULL, '["Lívio Sansone"]', 'Editora da Unicamp', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Estação etnográfica Bahia recupera um capítulo fundamental da história dos Estudos Afro-brasileiros que elegeu a Bahia como um repositório nacional e continental da africanidade entre os anos 1930 e 1960. Esse não foi um processo puramente local, dado pela indiscutível abundância das sobrevivências culturais africanas na Bahia, mas um produto de relações transnacionais frequentemente desiguais entre forasteiros e anfitriões , observadores e praticantes do candomblé, intelectuais, políticos, artistas e lideranças religiosas. Como afirma o autor: No caso do Brasil e mais especialmente da Bahia, a presença e o olhar de pesquisadores estrangeiros e de agendas acadêmicas e políticas estabelecidas em outros lugares não só influenciaram o mundo do candomblé a partir do final dos anos 1930 … , mas se tornaram parte integrante desses fenômenos sociais . Tais estudos, em contrapartida, tiveram um impacto decisivo na formação do campo de Estudos Africanos nos Estados Unidos e na agenda transnacional dos Estudos de Relações Raciais. (Julio Simões)', '["Afro-Brazilian studies","Candomblé","transnational relations","Bahia","history of anthropology","1930s-1960s"]', '10.7476/9788526816602', '9788526815902', 'https://books.scielo.org/id/zs425', NULL, NULL, 'https://books.scielo.org/id/zs425/cover/cover_thumbnail.jpeg', 320, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-zs9jn', 'zs9jn', 'O pós-colonialismo e a literatura: estratégias de leitura', NULL, '["Thomas Bonnici"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Após cinquenta anos de debates, a teoria e a literatura pós-coloniais proporcionaram parâmetros teóricos para explicar o fenômeno da reescrita dos textos clássicos, fomentar a urgência da prática de uma releitura e realçar uma desconstrução da literatura contemporânea inglesa. A literatura brasileira e latino-americana, também marcada pelo colonialismo, não pode ficar alheia a essa nova visão estética.', '["postcolonialism","postcolonial literature","reading strategies","rewriting of classical texts","re-reading","Brazilian literature","Latin American literature","colonialism"]', '10.7476/9788576285847', '9788576284277', 'https://books.scielo.org/id/zs9jn', NULL, NULL, 'https://books.scielo.org/id/zs9jn/cover/cover_thumbnail.jpeg', 377, 15, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-zscr6', 'zscr6', 'A coisa obscura: mulher, sodomia e Inquisição no Brasil colonial', NULL, '["Lígia Bellini"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2014, '2014-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A obra é uma analise de documentos e registros das confissões e denúncias de casos de mulheres sodomitas e feiticeiras, feitos pela Inquisição portuguesa por ocasião das visitações ao Brasil. Ligia Bellini, foca nos registros de relações afetivas e sexuais entre mulheres que viveram no Nordeste brasileiro, no final do século XVI e procura compreender e informar sobre as concepções e conhecimentos existentes, no período em questão, a respeito da anatomia e fisiologia e os modos como podiam transgredir os corpos femininos.', '["women","sodomy","Portuguese Inquisition","witchcraft accusations","confession","colonial Brazil","Northeast Brazil","late 16th century","female sexuality","gender and the body"]', '10.7476/9786556303734', '9788523212568', 'https://books.scielo.org/id/zscr6', NULL, NULL, 'https://books.scielo.org/id/zscr6/cover/cover_thumbnail.jpeg', 113, 13, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-zt4fg', 'zt4fg', 'Urgências e emergências em saúde: perspectivas de profissionais e usuários', NULL, '["Armelle Jacquemot"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2005, '2005-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'A obra pretende desvendar o que seja uma urgência ou uma emergência em saúde a partir de duas perspectivas: a dos usuários e a dos profissionais da rede pública. A autora mostra um universo dinâmico e complexo a partir de um trabalho antropológico realizado na Faculdade de Medicina de Marília, em São Paulo. São decisões médicas, muitas vezes de suma importância para a manutenção da vida, muitas vezes questionáveis sob o ponto de vista ético. Cabe lembrar que o livro não só trabalha com a dicotomia médico/paciente, mostrando para o leitor outros atores envolvidos no trabalho na emergência e revelando que muitas vezes as ações médicas são antecedidas por pequenos passos e atitudes peculiares de significativa importância que não podem ser desconsiderados, como a de um motorista de ambulância ou o porteiro do hospital.', '["emergency care","emergency department","public health services","clinical decision-making","medical ethics","physician-patient relationship","hospital staff","ambulance drivers","hospital porters","medical anthropology","patient perspectives"]', '10.7476/9788575413784', '9788575413784', 'https://books.scielo.org/id/zt4fg', 'https://books.scielo.org/id/zt4fg/pdf/giglio-9788575413784.pdf', NULL, 'https://books.scielo.org/id/zt4fg/cover/cover_thumbnail.jpeg', NULL, 25, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-zt7w6', 'zt7w6', 'Dois ensaios sobre utopia', NULL, '["João Almino"]', 'Editora Universidade de Brasília', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O tema da utopia continua atual e merece reflexão renovada. Este livro propõe interpretações originais e oportunas do clássico de Thomas More. No primeiro ensaio, a análise da estrutura narrativa da obra como peça literária, encenada por vários personagens, entre os quais quatro narradores, permite concluir que, por meio da dialética dos diálogos e do confronto entre os personagens, Utopia, em vez de elaborar uma demonstração linear, não sugere receitas prontas para serem aplicadas. Deixa espaço para o dissenso. Ser ficção é uma vantagem, que atenua a “distopia” presente no livro de More – “distopia” manifesta na organização totalitária de uma sociedade que se quer transparente para si mesma e onde não há divisão entre o público e o privado. Ela se evidencia também, como defende o segundo ensaio, na ordem internacional unidimensional, unilateral, em que as regras são impostas por um só ordenador do mundo, autossuficiente e todo-poderoso intérprete do bem, que se crê detentor dos valores da civilização.', '["utopia","Thomas More","narrative structure","dialogue","dissent","totalitarianism","public and private","international order"]', '10.7476/9786558460503', '9788523012052', 'https://books.scielo.org/id/zt7w6', NULL, NULL, 'https://books.scielo.org/id/zt7w6/cover/cover_thumbnail.jpeg', 52, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-zt9xy', 'zt9xy', 'Desafios contemporâneos da educação', NULL, '["Célia Maria David","Hilda Maria Gonçalves da Silva","Ricardo Pereira Ribeiro","Sebastião de Souza Lemes"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'DESAFIOS CONTEMPORÂNEOS DA EDUCAÇÃO 15da escrita de cartas por terceiros e por adultos em processo de alfabetização, os autores procuram discutir a representação que as pessoas pouco escolarizadas têm do seu saber.A partir dessa análise e trabalhando a questão dos conceitos de alfabetização e alfabetismo, chamam a atenção para a necessidade de refletir acerca das dimensões que envolvem o domínio da língua escrita."Sobre a escrita de pessoas pouco escolarizadas: de cartas e quadros", por sua vez, dedicou-se a promover o entendimento de por que os resultados obtidos por escolas públicas estaduais são tão distintos, mesmo quando se consideram escolas que contam com condições materiais e humanas semelhantes.As reflexões levantadas são fruto de uma pesquisa desenvolvida sobre as características da gestão das escolas públicas estaduais na cidade de Araraquara, no estado de São Paulo, tendo como foco as experiências bem-sucedidas desses atores sociais.Acreditamos que este livro possa contribuir das mais diversas formas para o debate acerca dos desafios colocados para a educação nos nossos tempos.Esperamos ainda que essa leitura possa estimular, ou melhor, suscitar experiências bem-sucedidas em direção à promoção de educação de qualidade para todas as pessoas.Eixo 1 Educação, culturas e realidade social Educação para a cidadania José Luís Bizelli 1 IntroduçãoQuando pensamos em educação é consenso interpretá-la como fonte para uma formação que permite trânsito na sociedade do conhecimento.Quase sempre a imagem socialmente construída diz respeito a um conjunto de atividades que habilita o indivíduo para perceber e desvendar os códigos das diferentes linguagens proporcionando interpretação crítica para o avanço da ciência, das artes e da tecnologia.No espelho acadêmico--científico atual, fortemente marcado pela competitividade expressa nos ranqueamentos internacionais, a imagem que aparece não evidencia nuanças de consensos sobre educação como fator ético de construção da cidadania.', '["citizenship education","literacy","illiteracy","public schools","school management","educational quality","knowledge society","education and culture"]', '10.7476/9788579836220', '9788579836220', 'https://books.scielo.org/id/zt9xy', 'https://books.scielo.org/id/zt9xy/pdf/david-9788579836220.pdf', NULL, 'https://books.scielo.org/id/zt9xy/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-zthrj', 'zthrj', 'A democracia inconclusa: um estudo da reforma sanitária brasileira', NULL, '["Sílvia Gerschman"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2004, '2004-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Trata do papel dos movimentos sociais em saúde no processo de reformulação da política de saúde, plasmado na Constituição de 1988 e denominado de Reforma Sanitária brasileira. Os percalços da sua implementação são analisados no contexto do processo de democratização do País ocorrido nos últimos 10 anos. A autora contribui para a interpretação da problemática da saúde no Brasil contemporâneo, sem a qual não se pode falar em democracia e cidadania. Através da leitura deste trabalho, os cientistas políticos e os profissionais de saúde poderão refletir acerca do lugar que ocupam no sistema e nos serviços de saúde, bem como das articulações de suas representações com a política de saúde.', '["Brazilian health reform","Brazilian Constitution of 1988","democratization","citizenship","healthcare workers","political representation","health system implementation"]', '10.7476/9788575415375', '9788575415375', 'https://books.scielo.org/id/zthrj', 'https://books.scielo.org/id/zthrj/pdf/gerschman-9788575415375.pdf', NULL, 'https://books.scielo.org/id/zthrj/cover/cover_thumbnail.jpeg', NULL, 57, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ztpr5', 'ztpr5', 'Judaísmo e Modernidade: suas múltiplas inter-relações', NULL, '["Helena Lewin"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A Universidade do Estado do Rio de Janeiro por intermédio de seu PROGRAMA DE ESTUDOS JUDAICOS, vinculado ao Instituto de Filosofia e Ciências Humanas, apresenta este volume intitulado “JUDAÍSMO E MODERNIDADE: suas múltiplas inter-relações”, produto do IV Encontro Brasileiro de Estudos Judaicos, realizado nessa Universidade.[Trecho retirado da apresentação do livro]', '["Judaism","modernity","Jewish studies","Jewish philosophy"]', '10.7476/9788579820168', '9788579820168', 'https://books.scielo.org/id/ztpr5', 'https://static.scielo.org/scielobooks/ztpr5/pdf/lewin-9788579820168.pdf', NULL, 'https://books.scielo.org/id/ztpr5/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-zvzdt', 'zvzdt', 'SAÚDE DA FAMÍLIA: boas práticas e círculos virtuosos', NULL, '["Flávio Goulart"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2007, '2007-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Health Professions', 'Este livro identifica práticas de bom governo e caminhos que conduzem a círculos virtuosos em relação à sua implantação. Trata-se de um texto que merece ser lido e debatido tanto por ampliar a compreensão do leitor sobre saúde e políticas públicas, como também porque propicia momentos agradáveis e de boa leitura para quem trabalhe ou milite no campo da saúde.', '["family health","good governance","virtuous circle","public health policy","health policy implementation","best practices"]', '10.7476/9788570785176', NULL, 'https://books.scielo.org/id/zvzdt', 'https://books.scielo.org/id/zvzdt/pdf/goulart-9788570785176.pdf', NULL, 'https://books.scielo.org/id/zvzdt/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-zw25x', 'zw25x', 'Seguridade social e saúde: tendências e desafios', NULL, '["Jordeana Davi","Cláudia Santos Martiniano","Lúcia Maria Patriota"]', 'EDUEPB', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro resulta desse processo e conta com a participação de docentes e discentes que integram o Grupo de Estudos, Pesquisas e Assessoria em Políticas Sociais (GEAPS) e o Núcleo de Estudos, Pesquisas e Práticas Sociais (NUPEPS). Apresenta discussões de grande importância para o Serviço Social, na medida em que se propõem refletir sobre Seguridade Social no Brasil, trazendo discussões mais amplas como: o financiamento e a mercantilizarão das políticas sociais; a trajetória histórica do controle social, especialmente no âmbito da saúde; e a gestão do trabalho no Sistema Único de Saúde (SUS) no contexto da reestruturação produtiva. Encontramos também nesta coletânea textos que apresentam resultados de investigação que tiveram por objetivo analisar de forma mais específica a realidade do município de Campina Grande (PB), no que se refere à implantação da Estratégia Saúde da Família, a partir da avaliação de profissionais da área; às concepções de aconselhamento de DST/Aids a gestantes por parte dos profissionais das Unidades Básicas de Saúde da Família; e às Organizações da Sociedade Civil de atendimento às pessoas com deficiência.', '["social security","social health","social control","social policy financing","health workforce management","productive restructuring","Family Health Strategy","primary care","civil society organizations","disability services","Campina Grande"]', '10.7476/9788578791933', '9788578791933', 'https://books.scielo.org/id/zw25x', 'https://books.scielo.org/id/zw25x/pdf/davi-9788578791933.pdf', NULL, 'https://books.scielo.org/id/zw25x/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-zw2ms', 'zw2ms', 'Proposições e novos olhares ao ensino de ciências', NULL, '["Maceno, Nicole Glock","Silva, Ana Carolina Araújo da"]', 'Editora UFFS', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esta obra descreve situações práticas e estudos sobre a sala de aula que permitem elaborar sentidos e significados sobre o ensino de Ciências, relacionando os pressupostos, os conteúdos, as concepções, os pensamentos e as representações sobre ele. Esse cenário produz, principalmente, um conjunto de hipóteses e de conceitos que possibilita interpretar, qualificar e compartilhar as teorias e novas estratégias úteis para a sala de aula. Oportuniza também o apoio à divulgação científica, cujas discussões convidam para a investigação de novos objetos de pesquisa, os quais aprofundam a temática sobre os currículos por meio de debates que consideram abordagens de ensino planejadas ou desenvolvidas na sala de aula. “Proposições e novos olhares ao Ensino de Ciências” estrutura-se em duas partes. Na primeira parte, articulam-se teorias de aprendizagem e de linguagem com as práticas das salas de aula, enfatizando objetos de estudo que permitem a interpretação dos fenômenos educacionais e abordagens que visam a melhoria do ensino e da aprendizagem. Na segunda, apresentam-se investigações que analisam os desdobramentos no uso de livros didáticos, da avaliação e de abordagens de ensino. Também se enfatiza como os temas sociocientíficos são relevantes para o planejamento curricular, para a experimentação e para incorporar a diversidade cultural na educação científica. Trata-se do segundo volume da Coleção Ensino de Ciências, organizada pelos pesquisadores Roque Ismael da Costa Güllich, Rosangela Inês Matos Uhmann e Rosemar Ayres dos Santos.', '["science education","teaching practice","learning theory","language and learning","textbooks","assessment","teaching methods","socioscientific issues","curriculum development"]', '10.7476/9786550190279', '9786550190279', 'https://books.scielo.org/id/zw2ms', 'https://books.scielo.org/id/zw2ms/pdf/maceno-9786550190279.pdf', NULL, 'https://books.scielo.org/id/zw2ms/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-zx6p9', 'zx6p9', 'Covid-19 no Brasil: cenários epidemiológicos e vigilância em saúde', NULL, '["Christovam Barcellos","Daniel Antunes Maciel Villela"]', 'Série Informação para ação na Covid-19 | Fiocruz', 'Brasil', 'SciELO Books', 'books', 2021, '2021-11-03', 'pt', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Mathematics', 'Apresentar um diagnóstico e constituir uma memória sobre a evolução da pandemia no Brasil, a partir de registros e análises de dados, sistemas de monitoramento e vigilância em saúde. É com esse intuito que o Observatório Covid-19 Fiocruz e a Editora Fiocruz publicam, em coedição, mais um e-book gratuito. Em três partes, que englobam um total de 25 capítulos, o título agrega os muitos desafios da comunidade científica brasileira - especialmente das equipes técnicas da Fiocruz - para a avaliação de cenários epidemiológicos diante da chegada do vírus Sars-CoV-2 ao país. Em um contexto que inclui dados reportados nos sistemas de vigilância epidemiológica, uso de modelos matemáticos e estatísticos, painéis de acompanhamento dos dados e sistemas de informação em saúde, o volume detalha os esforços e contribuições para a formulação de estratégias de mitigação e supressão da transmissão da doença. Este é o terceiro livro da série "Informação para Ação na Covid-19", que tem como objetivo reunir o conjunto de respostas, pesquisas e ações técnicas produzidas pela Fiocruz durante a pandemia. Com apoio da rede SciELO Livros, a iniciativa disponibiliza as obras exclusivamente em formato digital e acesso aberto.', '["COVID-19 pandemic","SARS-CoV-2","epidemiological scenarios","health surveillance","epidemiological surveillance system","mathematical model","health information systems","pandemic mitigation strategies","transmission suppression"]', '10.7476/9786557081211', '9786557081211', 'https://books.scielo.org/id/zx6p9', 'https://books.scielo.org/id/zx6p9/pdf/freitas-9786557081211.pdf', NULL, 'https://books.scielo.org/id/zx6p9/cover/cover_thumbnail.jpeg', NULL, 12, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-zx7hm', 'zx7hm', 'Luciano Berio: legado e atualidade', NULL, '["Flo Menezes"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'vanguarda musical brasileira, em especial da paulista, pelo viés dos ensinamentos de Willy Corrêa de Oliveira e, em alguma medida, também de Gilberto Mendes no Curso de Composição da USP, sobretudo no final dos anos 1970 e durante os anos 1980.Assim é que, de 24 a 26 de outubro de 2013, organizei, à frente do Studio PANaroma de Música Eletroacústica da Unesp, no Instituto de Artes do Câmpus de São Paulo, e em meio à SPA 2013 (Semana da Porta Aberta do Studio PANaroma), o Simpósio "Berio: 10 anos depois...".Levando a público oito conferências, ministradas por todos os meus orientados de Pós-Graduação àquela época e por músicos convidados (meus colegas da área da composição contemporânea Silvio Ferraz, Alexandre Lunsqui e Mauricio De Bonis), uma mesa-redonda e três concertos, o evento', '["Luciano Berio","Gilberto Mendes","contemporary composition","electroacoustic music","Brazilian composers"]', '10.7476/9788568334645', '9788568334645', 'https://books.scielo.org/id/zx7hm', 'https://books.scielo.org/id/zx7hm/pdf/menezes-9788568334645.pdf', NULL, 'https://books.scielo.org/id/zx7hm/cover/cover_thumbnail.jpeg', NULL, 7, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-zxmtm', 'zxmtm', 'Perspectivas pós-coloniais e decoloniais em relações internacionais', NULL, '["Aureo Toledo"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O que são perspectivas pós-coloniais e decoloniais? Quais autoras(es) e quais ideias têm ganhado destaque no debate contemporâneo? De que forma elas podem contribuir para a área de relações internacionais? A obra, dentre outros pontos, almeja discutir esses temas, mediante dois eixos. Na primeira parte, a partir de uma revisão das contribuições de autoras(es) específicas(os), pretende-se apontar as potencialidades das perspectivas pós-coloniais e decoloniais para temas ligados à área de relações internacionais. Na segunda parte, discutem-se criticamente temas centrais das tradições pós-coloniais e decoloniais, procurando avaliar como tais questões possibilitam pensar, de maneira original e inovadora, não apenas o internacional, mas também o Brasil.', '["postcolonial perspectives","decoloniality","international relations theory","postcoloniality","decolonial feminism","Brazil"]', '10.7476/9786556303987', '9786556300924', 'https://books.scielo.org/id/zxmtm', NULL, NULL, 'https://books.scielo.org/id/zxmtm/cover/cover_thumbnail.jpeg', 288, 5, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-zxnbn', 'zxnbn', 'Globalização e novos atores: a paradiplomacia das cidades brasileiras', NULL, '["Maria Clotilde Meirelles Ribeiro"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2014, '2014-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O objetivo central do livro é conhecer e analisar as estratégias de inserção internacional municípios brasileiros, promovendo preliminarmente uma visão geral do fenômeno paradiplomático e apresentando algumas linhas gerais e distinções verificadas nos vários continentes. O livro apresenta elementos que pretendem contribuir ainda para o aumento do interesse sobre a atuação internacional dos governos subnacionais brasileiros, fomentando novas pesquisas no campo.', '["paradiplomacy","Brazilian cities","subnational governments","municipal internationalization","globalization","new actors"]', '10.7476/9788523212018', '9788523212018', 'https://books.scielo.org/id/zxnbn', 'https://books.scielo.org/id/zxnbn/pdf/ribeiro-9788523212018.pdf', NULL, 'https://books.scielo.org/id/zxnbn/cover/cover_thumbnail.jpeg', NULL, 8, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-zyp2j', 'zyp2j', 'Da lavoura às biotecnologias: agricultura e indústria no sistema internacional', NULL, '["David Goodman","Bernardo Sorj","John R. Wilkinson"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro cresceu da convicção de que as análises contemporâneas da agricultura e da mudança social rural alcançaram um impasse. Dentro da tradição marxista, o significado do desenvolvimento tecnológico foi continuamente distorcido na medida em que as categorias teóricas e ideológicas do marxismo clássico foram alargadas para incorporar as estruturas sociais rurais modernas. Por sua vez, as contribuições neoclássicas, embora levando em conta a questão crucial da inovação, reduziram-na ao problema genérico da substituição de fatores. As duas abordagens, seja na linguagem da "penetração" ou da "modernização" capitalista, trataram do problema da agricultura, tal como ele é condicionado pela peculiaridade das relações sociais, por um lado, e pelas proporções entre os fatores, por outro.', '["agricultural biotechnology","agricultural technology","rural social change","neoclassical economics","agricultural innovation","factor substitution","capitalist modernization","agricultural sector","international system","technological progress"]', '10.7476/9788599662298', '9788599662298', 'https://books.scielo.org/id/zyp2j', 'https://books.scielo.org/id/zyp2j/pdf/goodman-9788599662298.pdf', NULL, 'https://books.scielo.org/id/zyp2j/cover/cover_thumbnail.jpeg', NULL, 42, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-zyvgp', 'zyvgp', 'Peixes e águas da Chapada Diamantina - Bahia: vida e história no alto rio Paraguaçu', 'vida e história no alto rio Paraguaçu', '["Alexandre Clístenes de Alcântara Santos","LUISA M. SARMENTO-SOARES","Ronaldo Fernando Martins Pinheiro"]', 'UEFS Editora', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Environmental Science', 'Nos contrafortes da Serra do Espinhaço na Bahia a Chapada Diamantina é o divisor natural de águas interbacia do rio São Francisco e bacias da rede de drenagem da Mata atlântica, rumo ao litoral ponto matas, campos rupestres, rios, lagoas e marimbus distinguem essas terras, habitadas por pescadores quilombolas e caboclos, e que hoje desperta o fascínico de turistas e ambientalistas. O rio Paraguaçu se destaca por uma história geográfica única, que desenhou a riqueza e variedade de ambientes aquáticos e também pela presença de peixes que só ali existem ponto diante da fragilidade e marcado endemismo da fauna aquática da Chapada Diamantina trazemos a você leitor, um pouco sobre as espécies, seus ambientes, as potenciais ameaças e caminhos para dissolver conflitos e conceber soluções. Venha com a gente e boa leitura!', '["Chapada Diamantina","Paraguaçu River","freshwater fish","aquatic fauna","endemism","São Francisco River basin","Atlantic Forest","caboclo communities","environmental hazards","Serra do Espinhaço"]', '10.7476/9788555921650', '9786589524434', 'https://books.scielo.org/id/zyvgp', NULL, NULL, 'https://books.scielo.org/id/zyvgp/cover/cover_thumbnail.jpeg', 137, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-zyx3r', 'zyx3r', 'Controle da tuberculose: uma proposta de integração ensino-serviço', NULL, '["Maria José Procópio"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2014, '2014-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'III IVFoto do prédio do Instituto Brasileiro para Investigação da Tuberculose, criado em 1927, na Bahia.Acervo: Casa de Oswaldo Cruz.15 Quem acompanhou este projeto, na sequência das sete edições, sabe que ele sempre esteve em evolução, registrando as transformações políticas, sociais e econômicas aqui e no mundo todo.Foram usadas referências de conferências, fóruns, resoluções e deliberações da Assembleia Geral da Organização Mundial da Saúde (OMS).Portanto, a publicação é muito mais do que um conteúdo para ensino ou consulta: é um devir da nossa saúde pública e do problema da tuberculose.Pensamos que este livro é um olhar brasileiro sobre si mesmo.É uma síntese das grandes questões que os profissionais de saúde e os estudantes enfrentam entre as atividades didáticas e seu agir em qualquer circunstância.Além de discutir o problema da tuberculose, procura refletir sobre o SUS em termos da nossa sociedade e das formulações teóricas sobre a sua evolução.Aproveitamos para, em nosso nome e de todos os nossos colegas do Centro de Referência Professor Hélio Fraga, reconhecer o papel do Dr.Germano Gerhardt, pelo seu pioneirismo ao participar da 1ª edição deste livro.Por fim, importa destacar que a nova edição insere-se no esforço ora desenvolvido, no âmbito da Fiocruz, de criação de um programa institucional para enfrentamento da tuberculose, denominado Fio-Tb.A criação do Fio-Tb é a resposta da Fiocruz à necessidade de uma instância de articulação, convergência e otimização entre suas diversas unidades para, de forma coletiva e inovadora, enfrentar a questão da tuberculose nas suas várias dimensões: técnico-científica, política, humana e social.Este livro, sob novos enfoques conceituais e diretrizes didático-pedagógicas, leva-nos à convicção de que seus autores sempre estiveram no caminho certo para o fortalecimento do controle da tuberculose em nosso país, tornando o sonho de 1987, época da primeira edição, realidade.', '["tuberculosis control","teaching-service integration","health professions education","Unified Health System (SUS)","tuberculosis epidemiology","tuberculosis prevention","Instituto Oswaldo Cruz","public health policy"]', '10.7476/9788575415658', '9788575415658', 'https://books.scielo.org/id/zyx3r', 'https://books.scielo.org/id/zyx3r/pdf/procopio-9788575415658.pdf', NULL, 'https://books.scielo.org/id/zyx3r/cover/cover_thumbnail.jpeg', NULL, 15, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-zz46v', 'zz46v', 'Os jovens e a História: Brasil e América do Sul', NULL, '["Luís Fernando Cerri"]', 'Editora UEPG', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'o continente americano no contexto mato-grossense ........', '["youth","history education","Brazil","South America","Mato Grosso"]', '10.7476/9788577982486', '9788577982486', 'https://books.scielo.org/id/zz46v', 'https://books.scielo.org/id/zz46v/pdf/cerri-9788577982486.pdf', NULL, 'https://books.scielo.org/id/zz46v/cover/cover_thumbnail.jpeg', NULL, 5, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-zz66x', 'zz66x', 'Leitura e escrita como espaços autobiográficos de formação', NULL, '["Maria Rosa Rodrigues Martins de Camargo"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'LEITURA E ESCRITA COMO ESPAÇOS AUTOBIOGRÁFICOS DE FORMAÇÃOA composição deste tema vem em gestação encoberta, desde as primeiras reflexões que me tocaram, à medida que a preocupação com o ato de escrever vai se tornando arte; vai se deixando ver nos embates de refinada interlocução, ao orientar os trabalhos de pesquisa de mestrado e de doutorado, e toma corpo na concretude deste material que ora se articula na forma de um livro.De início, situando-se mais no campo da intuição do que propriamente fundamentada teoricamente, a inter-relação entre o ato de ler e o do escrever parecia, de modo insistente, jogar seus tentáculos para assegurar, de algum modo, um percurso de formação; de formação acadêmica, intelectual, cultural, profissional; para orientandas e orientadora.Não demorou muito a aparecer a proposta para que, ao longo do percurso de suas pesquisas, as autoras de cada texto se posicionassem em primeira pessoa, como uma forma possível de articularem suas reflexões a respeito do objeto de estudo eleito.Com o andar das letras escritas, das reflexões que se abriam em possibilidades compartilhadas, porque passíveis de serem lidas, por outros, por tantos outros, fomos percebendo que escrever, e ser, na primeira pessoa, não era imperativo, criava espaços contundentes de projeções, de entrelaçamentos que abarcavam as intensas lhes possibilitaram, em diferentes épocas e contextos, leituras de si mesmos e do outro no exercício do ensinar, do aprender, do viver... Uma aproximação com práticas de escrita e leitura mais intimista, a das cartas pessoais, e as possibilidades que estas oferecem para conhecer sujeitos expressivos em suas relações, mais ou menos intensivas, consigo próprios e com seus correspondentes, por meio dos textos que escrevem, é o que propõe Vivian C. C. dos Santos no texto intitulado Fazeres autobiográficos e cartas pessoais.Leitura e escrita, práticas culturais que transitam também por processos de alfabetização, mais ou menos formais.No texto intitulado A leitura compartilhada das peças didáticas de Bertolt Brecht e os espaços para a produção de sentidos e significações, Natália K. R. Gonçalves discute a prática da leitura compartilhada das peças didáticas com um grupo de professoras, que propiciou análises, questionamentos, reformulações de ideias acerca da alfabetização e reflexões sobre a própria prática pedagógica, e sujeitos (atores/ autores) envolvidos neste processo.Ainda focalizando atores envolvidos nas relações de ensino e aprendizagem, mas em um contexto diferente, o de mulheres em processo de alfabetização, Renata R. de Araújo tece, no texto intitulado Os paradigmas da ciência e suas influências na constituição do sujeito, considerações acerca dos diferentes saberes que se aliam na escola, a fim de possibilitar que esta se constitua como espaço de interações entre os sujeitos.Foi também em uma classe de Educação de Jovens e Adultos que Thais Surian, desenvolvendo sua pesquisa de mestrado, encontrou alunas escritoras.Com os escritos de uma dessas alunas, em conjunto com escritos de duas outras mulheres escritoras, Carolina Maria de Jesus e Marguerite Duras, a autora compõe o texto Alinhavando contextos sociais escritos, em que traz questionamentos sobre quem são esses sujeitos -mulheres que escrevem e os contextos sociais em que estão inseridas.Em Modos de ser criança, Sibele A. Ribeiro busca aproximar-se daquilo que crianças falavam sobre a escola e também sobre suas vidas, sobre ser criança, sobre os adultos, sobre os modos pelos quais veem o mundo, seus brinquedos, suas brincadeiras e seus amigos; tal aproximação possibilitou reflexões sobre o que pode ser o mundo da criança, onde imaginar, transformar, criar constituem atributos muito próprios.Na elaboração de uma escrita de si, apoiada na memória enquanto recurso de (auto)formação, Josélia G. Neves contextualiza o local onde desenvolveu sua pesquisa de doutorado, o estado de Rondônia, uma parte da Amazônia brasileira.Uma busca dos prováveis entrelaçamentos entre cultura escrita e narrativa autobiográfica podem significar possibilidades', '["autobiographical writing","reading and writing","personal letters","first-person narration","doctoral students","academic training","literacy","self-reflection","writing instruction","writing as a way of being"]', '10.7476/9788579831263', '9788579831263', 'https://books.scielo.org/id/zz66x', 'https://books.scielo.org/id/zz66x/pdf/camargo-9788579831263.pdf', NULL, 'https://books.scielo.org/id/zz66x/cover/cover_thumbnail.jpeg', NULL, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-zz9q9', 'zz9q9', 'Judiciário e economia no Brasil', NULL, '["Armando Castelar"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Economics, Econometrics and Finance', '[...] O trabalho foi concebido com um duplo objetivo: desenvolver uma metodologia para medir os custos econômicos do mau funcionamento do sistema judicial e aplicar essa metodologia ao caso brasileiro, obtendo estimativas numéricas desses custos.', '["judiciary","judicial performance","Brazilian judiciary"]', '10.7476/9788579820199', '9788579820199', 'https://books.scielo.org/id/zz9q9', 'https://books.scielo.org/id/zz9q9/pdf/castelar-9788579820199.pdf', NULL, 'https://books.scielo.org/id/zz9q9/cover/cover_thumbnail.jpeg', NULL, 22, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-zz9yp', 'zz9yp', 'Maringá de todos os santos? Orixás, voduns, inquices e guias', NULL, '["Eronildo José da Silva"]', 'EDUEM', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A obra Maringá de todos os santos? Orixás, Voduns, Inquices e Guias busca, a partir da observação da negação da presença negra em Maringá, revelar tal presença, escondida que está em suas expressões religiosas. O ponto de partida foi o evento que ocorreu em 2008 e que chamou muito a minha atenção pelo seu título, ‘Maringá de Todos os Santos e de todas as culturas’, dando a entender que também se referia às divindades ou entidades que compõem o panteão das religiões afro-brasileiras.', '["Afro-Brazilian religions","orixás","Vodun","Maringá"]', '10.7476/9786587626147', '9786586383744', 'https://books.scielo.org/id/zz9yp', NULL, NULL, 'https://books.scielo.org/id/zz9yp/cover/cover_thumbnail.jpeg', 236, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-zzvdf', 'zzvdf', 'A Institucionalização da farmácia brasileira: Rio de Janeiro e Bahia, 1808-1891', NULL, '["Amanda Peruchi"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Uma história minuciosa da institucionalização da ciência farmacêutica em território brasileiro ao longo do século XIX. A autora, ao contrário do que se tem tornado habitual em estudos do gênero produzidos nas últimas décadas, não está interessada em descontruir as verdades do saber farmacêutico, ou em revelar os supostos mecanismos ocultos de dominação que tal saber engendra, ou em denunciar as exclusões que a sua racionalidade supostamente promove ou, menos ainda, em dar voz àqueles que seriam as vítimas de tal exclusão – os tais saberes alternativos calados ou lançados à margem. Sua empreitada tem ambições menos grandiosas, mas muito mais precisas e instrutivas. Em A Institucionalização da Farmácia Brasileira, Peruchi quer tão somente mapear a emergência e a consolidação, em solo nacional, de uma ciência que ganhou poderoso impulso na Europa setecentista, com o avanço da química moderna e das ciências biológicas. E que despontou, no Oitocentos, um pouco por todo lado no Ocidente, como auxiliar indispensável das ciências médicas no seu empenho de tomar para si a missão de zelar pela preservação da saúde e da vida dos povos.', '["history of pharmacy","pharmaceutical sciences","Rio de Janeiro","Bahia","19th century","Brazil","modern chemistry","history of medicine","health preservation"]', '10.7476/9786557082218', '9786557081815', 'https://books.scielo.org/id/zzvdf', NULL, NULL, 'https://books.scielo.org/id/zzvdf/cover/cover_thumbnail.jpeg', 298, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
